// Crimson-Desert-Wiki — Datenbestand, am 23.08.2026 aus index.html ausgelagert.
// REIHENFOLGE IST TRAGEND: Bloecke referenzieren frueher definierte (TDZ) — nicht umsortieren,
// Datei laedt als klassisches Script-Tag (src) VOR dem Hauptscript in index.html.
// Enthaelt: ITEMS, ITEM_BEREICHE, SANCTUM_GUIDE, CHAPTERS, SIDE_QUESTS
const ITEMS=[
  {name:"Hunter's Sigil",cat:"Pet-Ausrüstung — Vogel",detail:"Neu mit Patch 1.13.00. Ausrüstungs-Sigil für Vogel-Haustiere: Ausgerüstet lässt es den Vogel selbstständig Beute (prey) und Sammelobjekte passend zu seiner Spezialisierung apportieren — eine reine Sammel-/Loot-Funktion, kein Kampf. Gegenstück zum 'Amulett der Tapferkeit' (Kampf); pro Vogel entscheidet man sich faktisch für eine der beiden Rollen. Interner Item-Code deutet auf ein Pet-Amulett hin.",loc:"Verkauf durch die wandernde Pet-Händlerin Lacey (kein fester Stand) für 800 Kupfer (= 8 Silber; questlog 1004315) — tagsüber auf den Hauptwegen um Pororin/Florindale (Hernand) anzutreffen, z.B. morgens beim großen Baum in Florindale. Voraussetzung: Abschluss der Trembling-Woods-Questreihe (bereits erfüllt, wer via Totempfahl der Bindung Vögel gezähmt hat). Quelle: keengamer, thegameswiki, VULKK.",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_cd_pet_huntable_amulet.webp"},
  {name:"Sigil of Valor",cat:"Pet-Ausrüstung — Vogel",detail:"Pet-Ausrüstungs-Sigil, das ein Pet aktiv am Kampf teilnehmen lässt: Es greift nahe Gegner automatisch an (wirkt vor allem gegen starke Gegner mit viel HP), statt nur nach dem Kampf zu looten. Anlegbar auf Hunde und Baby-Wyverns; seit Patch 1.13.00 auch auf Uhrwerk-Adler und Phönix (die Freischaltung war in 1.11.00 zunächst wieder gestrichen worden). Nicht mit dem neuen 'Amulett des Jägers' (reine Sammel-Funktion) verwechseln.",loc:"Bei der wandernden Geheimhändlerin Lacey (Shai-NPC) im Raum Pororin/Florindale (meist im Nebendorf Florindale), 800 Kupfer (= 8 Silber; per questlog bestätigt). Vorbedingung laut Guides: Abschluss der 'Unreachable Village'-Fraktions-Questreihe — unbestätigt, beim 'Amulett des Jägers' nennen die Quellen stattdessen die Trembling-Woods-Reihe. Quelle: questlog.gg (Item 1004287), Gfinity Esports, game8, PC Gamer. Hinweis (Prüfung 11.08.2026): Die drei Guide-Quellen waren zeitweise nicht abrufbar.",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_cd_pet_brave_amulet.webp"},
  {name:"Firefly Lantern",cat:"Werkzeug — Lampe",detail:"Legendäre Laterne, die seit Generationen im Langblattwald weitergegeben wird. Wenn ihr Licht scheint, steigen kleine glühwürmchenartige Geister auf und lindern Wunden mit warmer Energie. Zusatzfähigkeit 'Firefly Dust' (Laterne per Quick Slot einschalten, laut questlog); Werte (Heilmenge, Dauer) nicht erfasst. Fextralife: beim Schmied nicht verbesserbar, Basispreis 240; der Text dort („Only those acknowledged by the spirits of the forest can obtain this lantern“) nennt weder Verpassbarkeit noch Fraktionsentscheidung.",loc:"Belohnung der Quest 'Heller Langblattwald' (Langblatt-Stamm, Pailune): Mission 'Aufgelöster Nebel' bzw. 'Deliver the news of Moren's defeat' (Nachricht vom Sieg über Moren the Mistwood Huntmaster überbringen). questlog führt beide Missionen mit denselben Belohnungen (u. a. Schattenblattbogen, Sklavengladiator-Brandmarkungsspeer, Rosenhornhirsch). Freischaltung des Langblatt-Stamms über die Skoghorn-Kette 'Seelenhirte' (White Horn); die Pailune-Miliz-Voraussetzung nennen Sportskeeda, Fextralife und gamerguides. Keine Quelle führt die Laterne als verpassbar. Quelle: questlog (Item 1000858, Mission 1000549), camzillasmom, Sportskeeda, Fextralife, gamerguides.com",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_lantern_0009_on.webp"},
  {name:"Lantern",cat:"Werkzeug — Lampe",detail:"Basis-Laterne und tragbare Lichtquelle zum Ausleuchten dunkler Bereiche (Kerze oder Öl in einem Eisenrahmen). Sie heftet sich an Kliffs Ausrüstung und bleibt entzündet, ohne die Hände für Kampf oder Erkundung zu blockieren; sie kann manuell hochgehalten (gerichtetes Licht) oder im Auto-Modus genutzt werden. In der Nähe von Erinnerungsfragment pulsiert sie und leuchtet blau, als Signal, dort mit dem Visione zu lesen, und hilft, Spuren und Hinweise für bestimmte Rätsel sichtbar zu machen. Aktivierung: L1/LB/Strg halten; Ein/Aus über das Ausrüstungs-Radialmenü (Links-D-Pad bzw. F2). Am Blacksmith verbesserbar.",loc:"Standardmäßig im Verlauf der Quest 'Unknown Space' (Prolog 'Tiefe Nacht') freigeschaltet. Ersatz beim Gemischtwarenladen für 10 Kupfer überall in Pywel kaufbar. Quelle: Game8, Fextralife",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_lantern_on.webp"},
  {name:"Torch",cat:"Werkzeug — Lampe",detail:"Eine Fackel aus öldurchtränktem Tuch um ein Stockende. Große, helle Flamme, die einen weiten Bereich ausleuchtet. Kann notfalls als Waffe dienen (geringer Schaden); wegen der Brandgefahr ist Vorsicht geboten. Nicht am Blacksmith verbesserbar.",loc:"Basispreis 85; die Bezugsquelle ist auf der Fextralife-Seite nicht angegeben, und in den questlog-Spieldaten gibt es kein Item 'Fackel' (nur die eigenständigen Gegenstände 'Tripod Guide Torch' und 'Tripod Guardian Torch'). Quelle: Fextralife",miss:false,conf:"medium",icon:"cd_assets/items/torch.webp"},
  {name:"Blue Scout Lantern",cat:"Werkzeug — Lampe",detail:"Eine Laterne für Kundschafter, die Neuigkeiten aus ganz Pywel schneller als alle anderen sammeln. Ihr Licht soll den Weg ins Abenteuer weisen und helfen, Pywels zahllose Geheimnisse aufzudecken. Keine Statboni; nicht am Blacksmith verbesserbar.",loc:"Bezugsquelle auf der Wiki-Seite nicht angegeben. Als einzigartige Laterne geführt. Quelle: Fextralife, Sportskeeda",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_lantern_0008_index02_on.webp"},
  {name:"Dark Fog Lantern",cat:"Werkzeug — Lampe",detail:"Eine dekorative, regen- und windfeste Laterne. Ihr Licht durchdringt selbst die dichtesten Tiefen jeder Nebelwolke, daher ihr Name. Nützlich in stark vernebelten Gebieten. Basispreis 240.",loc:"Missionsbelohnung 'Deliver the scout report' (Quest 'Transzendentes Bauwerk', Haus Alfonso, Hernand). Quelle: questlog (Item 10046, Mission 4294964953), Fextralife, Sportskeeda",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_lantern_0003_on.webp"},
  {name:"Fancy Flame-Patterned Lantern",cat:"Werkzeug — Lampe",detail:"Eine mit Flammenmustern durchbrochene Laterne. Beim Entzünden flackern die Schatten und erzeugen eine eindrucksvolle Atmosphäre. Eher Dekoration als praktischer Nutzen.",loc:"Missionsbelohnung 'Deliver the news of victory' (Schritt der Mission 'Verfluchter Berg', Quest 'Weißer Schneesturm', Haus Lanford, Hernand; nach der Untersuchung der Hohenmark-Ruinen). Basispreis 240. Quelle: questlog (Item 10045, Mission 4294966498), Fextralife, Sportskeeda",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_lantern_0005_on.webp"},
  {name:"Flame Lantern",cat:"Werkzeug — Lampe",detail:"Eine robuste Laterne aus Eisen mit dünnem Eisenbeschlag in Form einer brennenden Flamme. Wegen ihres Gewichts und dekorativen Aussehens beliebt. Eine Refinement-Tabelle ist vorhanden, aber nur bis +0 dokumentiert (kein nennenswertes Upgrade).",loc:"Bezugsquelle nicht näher angegeben; Basispreis 240 (vermutlich Händler). Quelle: Fextralife",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_lantern_0004_on.webp"},
  {name:"Purple Scout Lantern",cat:"Werkzeug — Lampe",detail:"Eine Laterne für Kundschafter, die Neuigkeiten aus ganz Pywel schneller als alle anderen sammeln. Ihr Licht weist den Weg ins Abenteuer und hilft, Pywels Geheimnisse aufzudecken (gleiche Beschreibung wie Blaue Späher-Laterne, andere Färbung). Keine Statboni; nicht am Blacksmith verbesserbar.",loc:"Missionsbelohnung 'Check the news on the new fabric' (Quest 'Geschichten der delesyischen Händler', Auftrag 'Anfrage von Martina', Schneiderei Martina in der Burg Delesyia). Quelle: questlog.gg (Item 1003190, Mission 4294966142), crimsondb.gg, Fextralife",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_lantern_0008_index01_on.webp"},
  {name:"Shiny Blue Sea Lantern",cat:"Werkzeug — Lampe",detail:"Eine dekorative Laterne, beliebt bei den Shais; nachdem ein Shai sie ins Dorf brachte, verbreitete sie sich schnell. Ein goldener Rand mit blauem Glas macht sie im entzündeten Zustand besonders schön. Überwiegend dekorativ.",loc:"Bezugsquelle nicht angegeben; Basispreis 240 (vermutlich Händler). Als einzigartige Laterne geführt. Quelle: Fextralife, Sportskeeda",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_lantern_0002_on.webp"},
  {name:"Shroud Lantern",cat:"Werkzeug — Lampe",detail:"Eine fein gefertigte, hochwertige Laterne, dem Crimson-Desert-Stil ähnlich, aber subtil anders. Gebrauchsspuren am Griff deuten darauf hin, dass sie zuvor in der rechten Hand getragen wurde (vermutlich mit einer Waffe in der linken). Nicht am Blacksmith verbesserbar.",loc:"Bezugsquelle/Quest auf der Wiki-Seite nicht angegeben; nur über Fextralife belegt. Quelle: Fextralife",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_lantern_0006_on.webp"},
  {name:"Wooden Lantern",cat:"Werkzeug — Lampe",detail:"Eine einfache, leichte Laterne aus Holz, gefertigt aus leicht verfügbaren Materialien. Wird wegen der Brandgefahr seltener genutzt als Metalllaternen. In der Refinement-Tabelle nur +0 (kein nennenswertes Upgrade).",loc:"Händler Wilmer (240 Kupfer); außerdem Belohnung dreier Missionen 'Return to the merchant': zwei in der Reihe 'Eine helfende Hand für Delesyia' (u. a. Wiederaufbau der Transitstation bei Franklin), eine in 'A Favor for Crimson Desert'. Quelle: questlog (Item 1001849), Fextralife, Sportskeeda",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_lantern_0007_on.webp"},
  {name:"Bernor's Pickaxe",cat:"Werkzeug — Bergbau",detail:"Effekt: Mining Yield Up Lv 2 (höhere Ertragsstufe als Feine Spitzhacke) mit \"Chance to Mine Additional Materials\" 20% -> 30%. Wird aus einer Blaupause gefertigt (u. a. 30 Hochwertiges Holz, 20 Eisenerz, 10 Stabile Tierhaut, 10 Diamanten bei einem Schmied). Beste reguläre Spitzhacke für maximalen Erzertrag.",loc:"Blaupause kaufbar bei Bernor im Mineralienladen von Festung Manub in Tashkalp (Crimson Desert / Wüstenregion); zuvor Festung Manub befreien und Bernors Vertrauen (Geschenke) aufbauen. Quelle: VULKK; Quelle: Nerdschalk; Quelle: GameRant",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_pickaxe_0003.webp"},
  {name:"Fine Pickaxe",cat:"Werkzeug — Bergbau",detail:"Effekt: Mining Yield Up Lv 1 mit \"Chance to Mine Additional Materials\" 20% -> 30% (steigt durch Refinement). Höhere Grundchance auf Zusatzmaterialien als die Standard-Spitzhacke, bei gleicher Ertragsstufe. Wird aus einer Blaupause gefertigt.",loc:"Blaupause kaufbar im Mineralienladen in Steinbruch Karin, Hernand. Quelle: VULKK; Quelle: Game8",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_pickaxe_0001_index01.webp"},
  {name:"Mining Knuckledrill",cat:"Werkzeug — Bergbau",detail:"Elektrisches Bergbau-Werkzeug (nur von Kliff nutzbar). Effekt: Mining Yield Up Lv 1 -> 2 durch Verbesserung, \"Chance to Mine Additional Materials\" 10% -> 30%; voll aufgewertet erreicht es die Erträge von Bernors Spitzhacke und sammelt abgebautes Erz zusätzlich automatisch ein. Dieses Werkzeug ist zugleich eine Knuckles-Waffe und erscheint auch auf der Seite Waffen.",loc:"Belohnung für den Sieg über den Boss Marnis Steinbruchmaschine (Faktions-Quest \"Gestohlener Steinbruch\"); zusätzlich als Drop von Blut-Banditen in Steinbruch Karin sowie per Missions-Dispatch (Vorwork Armory in Demeniss oder Steinbruch Karin in Hernand) nach Abschluss der Forschung \"Forschung zur Konstruktion elektrischer Werkzeuge\" am Dewhaven Keep Institute in Delesyia. Quelle: VULKK; Quelle: Game8; Quelle: Nerdschalk",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_phm_13_fist_0014_r.webp"},
  {name:"Pickaxe",cat:"Werkzeug — Bergbau",detail:"Standard-Spitzhacke (Attack 8, Fähigkeit \"Mining Mastery\"). Effekt: Mining Yield Up Lv 1 mit 10% Chance auf zusätzliches Erz pro Schlag. Bei voller Verbesserung (+10 Refinement) steigt der Angriffswert auf 31, die 10%-Bonuschance bleibt aktiv. Erhöht den Erz-/Mineral-Ertrag deutlich gegenüber Notmethoden wie Kraftfaust oder Explosivpfeilen.",loc:"Standard-Werkzeug, früh erhältlich bei Händlern/Schmieden in Hernand (z.B. Ausrüstungsladen). Quelle: Fextralife; Quelle: Nerdschalk; Quelle: VULKK",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_pickaxe_0001.webp"},
  {name:"Demenissian Chainsaw",cat:"Werkzeug — Holzfällen",detail:"Elektrische Kettensäge (laut Patch 1.11.00 vom 12.06.2026 auch von Damiane und Oongka ausrüstbar, zuvor nur Kliff); fällt Bäume schneller. Effekt: Logging Quality Up Lv 1 -> 2 durch Verbesserung, \"Chance to Log Additional Timber\" 10% -> 30% - voll aufgewertet erreicht sie die Erträge von Olvalds Holzfälleraxt und sammelt gefälltes Bauholz zusätzlich automatisch ein.",loc:"Per Missions-Dispatch (Vorwork Armory in Demeniss oder Stahlspitzen-Arsenal in Delesyia) nach Abschluss der Forschung \"Donner - Forschung zum Bewegungsumwandlungsmechanismus\". Seit Patch 2.00.00 (25.08.2026) kann die Kettensäge im Camp gespendet werden (offizielle Notes, keine Gegenleistung genannt). questlog führt sie als Belohnung der Entsendung „Herstellung: Kettensäge“. Quelle: VULKK; Quelle: Game8; Patch-Notes 2.00.00",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_phm_13_fist_0016_r.webp"},
  {name:"Fine Logging Axe",cat:"Werkzeug — Holzfällen",detail:"Effekt: Logging Quality Up Lv 1 mit \"Chance to Log Additional Timber\" 20% -> 30%. Höhere Chance auf Hochwertiges Holz und (durch Refinement) auf zusätzliches Bauholz als die Standard-Axt. Wird aus einer Blaupause gefertigt.",loc:"Blaupause kaufbar im Gemischtwarenladen in Odeck, nordwestliches Pailune. Quelle: VULKK; Quelle: Game8",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_axe_0001_index01.webp"},
  {name:"Logging Axe",cat:"Werkzeug — Holzfällen",detail:"Standard-Fällaxt (Attack 8, Fähigkeit \"Logging Mastery\"). Effekt: Logging Quality Up Lv 1 zum Fällen und Zerteilen von Bäumen für Bauholz; bei voller Verbesserung (+10) zusätzlich 10% Chance auf zusätzliches Timber. Verschiedene Timber-Qualitäten werden zum Aufwerten der meisten Bogen und einiger Schilde benötigt.",loc:"Standard-Werkzeug: gratis durch Annahme von Anfrage von Turnali (Schmied in Hernand) oder Kauf im Gemischtwarenladen für 29 Kupfer (Flaschen-Symbol-Shops, u.a. in Pywell). Quelle: Game8; Quelle: Fextralife",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_axe_0001.webp"},
  {name:"Olvald's Logging Axe",cat:"Werkzeug — Holzfällen",detail:"Effekt: Logging Quality Up Lv 2 (höhere Qualitätsstufe als Feine Holzfälleraxt) mit \"Chance to Log Additional Timber\" 20% -> 30%. Beste reguläre Fällaxt, direkt von allen Charakteren nutzbar (langsamer als die Demeniss-Kettensäge). Wird aus einer gefundenen Blaupause gefertigt.",loc:"Blaupause liegt auf einem Tisch im Langastschatten-Versteck nördlich von Skallbucht, Pailune. Quelle: VULKK; Quelle: Game8",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_axe_0002.webp"},
  {name:"Broom",cat:"Werkzeug — Sammeln",detail:"Besen. In-Game-Beschreibung (Game8/crimsondb, verbatim): \"Cleaning Tool for Sweeping Floors\". Laut VULKK in zwei Quests benötigt (vom Spiel gestellt) und in der 'Pine Broom Challenge' (gegen Bären) eingesetzt; es existiert eine 'Robuster Besen'-Variante (questlog 1003848, bei Händlern für 85 Kupfer; Abyss-Sockel laut VULKK, im Item-Text nicht erwähnt).",loc:"Vom Spiel im Questkontext bereitgestellt; zusätzlich bei Händlern für 58 Kupfer kaufbar (questlog: u. a. Ronnard, Kiki, Wynstan). Quelle: questlog.gg, Game8, Fextralife, VULKK",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_broom_0001.webp"},
  {name:"Extra Large Bag",cat:"Werkzeug — Sammeln",detail:"Großer Beutel, der die Inventarkapazität dauerhaft um 10 Slots erweitert. Er liegt neben einem zerbrochenen Karren in den Hügel ohne Wiederkehr (nordöstlich von Hernand, südwestlich der Arboria-Werkstatt) und respawnt alle sieben Ingame-Tage, sodass man durch wiederholtes Einsammeln das Inventar bis zum 240-Slot-Maximum ausbauen kann. Es ist also kein Einmal-Item.",loc:"Fundort: am Straßenrand zwischen Hernand und Demeniss, neben einem zerbrochenen Karren in den Hügel ohne Wiederkehr; nächster Schnellreisepunkt Abyss-Nexus bei Karin-Quarry. Quelle: Game8, Gamer Guides, wccftech",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_inventorybag_0001.webp"},
  {name:"Fertilizer Sprayer",cat:"Werkzeug — Sammeln",detail:"Farm-Werkzeug, mit dem Dünger auf die Beete am Hof gesprüht wird, um Wachstum und Ernteertrag der Pflanzen zu steigern; es lassen sich mehrere Pflanzen auf einmal besprühen. Haltbarkeit: nerdschalk/The Games Wiki nennen ihn „ohne Verschleiß“, VULKK dagegen führt nur den Wassersprinkler als verschleißend (anders als Fertilizer und Schmiermittel), Gamer Guides nennen für den Schmiermittelsprüher begrenzte Haltbarkeit – die Quellen widersprechen sich, questlog führt keine Haltbarkeitsangabe. Ergänzt sich mit dem Wassersprinkler, mit dem zuvor bewässert wird.",loc:"Mission „Nährboden des Überflusses“ der Quest „Verlassene Fabrik“ (Elixir Factory, Kultivierungsraum; questlog: „A fertilizer sprayer used at the Elixir Factory was obtained“); zusätzlich am Schmied craftbar: Hochwertiges Holz 10, Eisenerz 5, Kupfererz 2, Gummi 1, Water 20 (questlog-Rezept 1008762, dasselbe wie bei Field und Schmiermittelsprüher). Quelle: questlog.gg (Mission 1001021), nerdschalk, The Games Wiki",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_phm_00_bag_0068.webp"},
  {name:"Field Pack",cat:"Werkzeug — Sammeln",detail:"Robuster Packen mit Ausrüstung und Feuermachwerkzeug. Im Spiel dient er nicht als Sammelwerkzeug, sondern als Herstellungszutat: Basis-Packs wie der Feldrucksack werden für Kuku-Rucksack-Upgrades am Kuku-Topf benötigt (jeder Basis-Pack ist als Herstellungsbasis austauschbar). Man sollte sie daher behalten und nicht verkaufen.",loc:"Verwendung: Herstellungsmaterial für Kuku-Rucksack-Upgrades bei Grimnirs Kuku-Shop (Kuku-Topf). Basis-Packs respawnen u.a. an der Totesmith-Gerberei beim Glenbright-Bauernhof. Quelle: Game8, GameRant, allthings.how",miss:false,conf:"high",icon:"cd_assets/items/field-pack.webp"},
  {name:"Field Sprayer",cat:"Werkzeug — Sammeln",detail:"Farm-Werkzeug zum Bewässern von Pflanzen; verkürzt die Wachstums- und Fruchtzeit. Haltbarkeit laut VULKK: begrenzt, Ersatz nötig (anders als Schmiermittel und Fertilizer) – Gamer Guides nennen dagegen für den Schmiermittelsprüher begrenzte Haltbarkeit; der Widerspruch ist ungeklärt (questlog ohne Haltbarkeitsangabe). Rezept durch Beobachten von Bauern in Demeniss (VULKK, 30.05.2026). Außerdem seltener Drop (12 %) bei „Fremder“-Gegnern und Mecha Farmer sowie Belohnung der Mission „Take the girl to the village“ (questlog).",loc:"Herstellung bei Schmieden wie Grimnir, Jofrua und Tibo (questlog: acht Schmiede-NPCs): 10 Hochwertiges Holz, 5 Eisenerz, 2 Kupfererz, 1 Gummi, 20 Water (questlog-Rezept 1008761). Quelle: VULKK (30.05.2026), questlog.gg (Item 1000198)",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_phm_00_bag_0046.webp"},
  {name:"Fine Fishing Rod",cat:"Werkzeug — Sammeln",detail:"Stabile Angel aus haltbarem Material, deren Flexibilität dem Zug großer Fische standhält; erste echte Upgrade-Stufe über der einfachen Angelrute. Sie verkürzt die Wartezeit zwischen den Bissen.",loc:"Bezug: Bauplan (Blaupause: Feine Angelrute) bei Grimrak im Back-Alley-Shop für 500 Kupfer (= 5 Silber; laut questlog auch bei Aegrin, Slywek, Thrak, Brek u. a.); fertige Rute laut questlog bei den Händlern Tranan und Varin für 3000 Kupfer (= 30 Silber). Die früheren Angaben 10 bzw. 45 Silber ließen sich nicht bestätigen. Herstellung beim Schmied: 10x Hochwertiges Holz, 10x Eisenerz, 3x Dicke Tierhaut, 10x Federn. Quelle: The Games Wiki, questlog.gg, crimsondesert.gaming.tools",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_fishingrod_0001_index01.webp"},
  {name:"Fishing Rod",cat:"Werkzeug — Sammeln",detail:"Basis-Angelrute. In-Game-Beschreibung (Game8/crimsondb, verbatim): \"For Catching Fish\". Grundwerkzeug fürs Angeln; aufgewertete Varianten (Feine Angelrute, Pororin-Angelrute, Krabbenangelrute) bilden die Angel-Werkzeugkette.",loc:"Kaufbar im Gemischtwarenladen in Hernand (nahe dem Bluemont-Anwesen). Quelle: Game8, Fextralife, VULKK",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_fishingrod_0001.webp"},
  {name:"Heavy Bucket",cat:"Werkzeug — Sammeln",detail:"Ein robuster Eimer aus stabilem Metall oder Holz. Laut Item-Text langlebig und vor allem an anspruchsvollen Arbeitsstätten genutzt; fasst große Mengen Wasser oder Sand. Dient dem Transport bzw. Sammeln von Wasser oder Sand.",loc:"Allgemeines Arbeitswerkzeug; konkreter Vendor/Fundort in den Quellen nicht benannt (Basispreis laut Fextralife 15; kein Eintrag in den questlog-Spieldaten – weder unter den 4.200 Sammel-/Verbrauchs-Items noch unter den 1.878 Ausrüstungsteilen findet sich ein „Schwerer Eimer“). Quelle: Fextralife, crimsondb.gg, crimsondesert.gaming.tools",miss:false,conf:"medium",icon:"cd_assets/items/heavy-bucket.webp"},
  {name:"Hoe",cat:"Werkzeug — Sammeln",detail:"Rechtwinkliges Farm-Werkzeug zum Jäten von Feldern und zum Bearbeiten des Bodens. Es wird zum Auflockern der Erde, zum Ausgraben von Pflanzen und zur Pflege der Felder eingesetzt und eignet sich für Detailarbeit auf engem Raum. Nutzbar von Kliff und Oongka, beim Schmied bis +10 verbesserbar (Refinement).",loc:"Bezug: Farm-Werkzeug, beim Schmied per Refinement (Materialien + Währung) bis +10 verbesserbar. Quelle: Fextralife, crimsondesert.gaming.tools",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_hoe_0001.webp"},
  {name:"Insect Gatherer's Pack",cat:"Werkzeug — Sammeln",detail:"In-Game-Äquivalent eines Insekten-/Schmetterlingsnetzes (kein klassisches 'Net'-Item); im Spiel 'Kuku-Rucksack des Insektensammlers' (questlog 1000845). Fängt automatisch nahe Insekten ein; wird über das Funktionsrad mit L2+R2/LT+RT aktiviert, funktioniert auch in der Luft und beim Sprinten, Abklingzeit 10 Sekunden. Nötig u. a. für die Challenge 'Tiny Citizens of Grasslands' (76 Insekten, davon 49 Schmetterlinge).",loc:"Blaupause durch Reinigen des Sanktums des Frevels (nach Besuch bei Lyselia, Witch of Humility). Herstellung bei Grimnir in der Kilnden-Werkstatt in Hernand (ab Kapitel 4): 1 Kuku-Rucksack, 3 Abyss Cells, Power Core – Ore of Resipiscence, Power Core – Crown of Shadows. Quelle: GameRant, PowerPyx",miss:false,conf:"high",icon:"cd_assets/items/insect-gatherers-pack.webp"},
  {name:"Kuku Gardening Pack",cat:"Werkzeug — Sammeln",detail:"Sammel-Rucksack, der automatisch alle Pflanzen in der Umgebung fernerntet und ins Inventar legt; Abklingzeit 10 Sekunden. Wird aus einem Kuku-Rucksack modifiziert (questlog-Rezept 'Kuku Plant Gatherer's Pack', Ergebnis-Item 'Kuku-Gärtnerrucksack'). Der Insect Gatherer's Pack wird ebenfalls aus einem Kuku-Rucksack gefertigt, nicht aus diesem Rucksack.",loc:"Blaupause von Lyselia (Green Witch of Humility) durch Reinigen des Sanktums der Verehrung am Berg Benus, Südost-Delesyia. Herstellung bei Grimnir in der Kilnden-Werkstatt (westlich der Hauptstadt Hernand): 1 Kuku-Rucksack, 3 Abyss Cells, Power Core – Ore of Resipiscence, Abbild der Kasteiung. Quelle: VULKK, TheGamer",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_phm_00_bag_0064.webp"},
  {name:"Large Farming Rake Scythe",cat:"Werkzeug — Sammeln",detail:"Eine Erntesense mit darüber montiertem Rechenaufsatz, der das geschnittene Getreide ordentlich auffängt. Vereint Schneiden und Einsammeln in einem Arbeitsgang und spart so Farm-Zeit. Am Schmied verfeinerbar.",loc:"Kaufbar bei Kikis Provisioner Shop im Demeniss-Territorium für 45 Münzen; Kiki im Hauptsiedlungsbereich aufsuchen. Quelle: nerdschalk, Fextralife, crimsondb.gg, questlog.gg, mapmaster.io",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_farmscythe_0003.webp"},
  {name:"Large Farming Scythe",cat:"Werkzeug — Sammeln",detail:"Große Sense mit langem Stiel, die im Stehen geschwungen wird, um Weizen oder Gras großflächig zu schneiden. Effizient für großflächige Arbeit zur Erntezeit. Beim Schmied über Refinement (Materialien + Währung) verbesserbar.",loc:"Bezug: Farm-/Ernte-Werkzeug, beim Schmied verbesserbar. Quelle: Fextralife, Gamer Guides, crimsondb.gg, questlog.gg",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_farmscythe_0001.webp"},
  {name:"Lubricant Sprayer",cat:"Werkzeug — Sammeln",detail:"Sprühgerät (Pack/Quickslot-Werkzeug), das Schmiermittel verteilt, um Reibung zwischen mechanischen Teilen zu verringern und Ausfälle zu verhindern. Wird aus dem Fernkampf-/Quickslot ausgerüstet, mit Sub-Attack gezielt und mit Heavy-Attack versprüht; laut Gamer Guides begrenzte Haltbarkeit mit Neufertigung danach (VULKK dagegen führt nur den Wassersprinkler als verschleißend; questlog ohne Haltbarkeitsangabe – Widerspruch ungeklärt). DE-Name „Schmiermittelsprüher“.",loc:"Fertigbar an der Schmiede (Kosten laut questlog-Rezept 1008763: 10 Hochwertiges Holz, 5 Eisenerz, 2 Kupfererz, 1 Gummi, 20 Water); das Rezept (zusammen mit Wassersprinkler und Düngersprüher) wird laut Guides freigeschaltet, indem man auf dem Ackerland westlich von Demeniss einem Bauern beim Besprühen seiner Felder zusieht, bis die Spray-Animation abläuft. Quelle: Gamer Guides, VULKK, crimsondesert.app, questlog.gg",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_phm_00_bag_0070.webp"},
  {name:"Magic Scythe",cat:"Werkzeug — Sammeln",detail:"Verzauberte Sense: erntet Gras oder Feldfrüchte über einen größeren Bereich als eine normale Sense und leuchtet auf, wenn man sich nahe sammelbaren Pflanzen oder Insekten befindet. Der Effekt ist bis zu 3-mal aufladbar, mit 5 Sekunden Abklingzeit zwischen den Ladungen. (Effekt sowie Lade- und Cooldown-Werte von VULKK und crimsondb übereinstimmend bestätigt.)",loc:"Per Mission-Dispatch craftbar in Florindale nach Abschluss der Pororin-Forschung (Petalton-Werkstatt, Lumiel-Forschungsbaum). Quelle: VULKK, crimsondb",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_farmscythe_0002.webp"},
  {name:"Mallet",cat:"Werkzeug — Sammeln",detail:"Holzhammer/Schlegel. In-Game-Beschreibung (Game8/crimsondb, verbatim): \"Used to Drive or Pound Nails\", zum Einschlagen von Nägeln. Utility-/Bauwerkzeug.",loc:"Kaufbar im Gemischtwarenladen in Hernand (nahe dem Bluemont-Anwesen). Quelle: Game8, Fextralife",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_hammer_0003.webp"},
  {name:"Peddler's Pack",cat:"Werkzeug — Sammeln",detail:"Trage-/Transport-Pack (Rucksack) zum Befördern von Waren, Materialien und Handelsgütern. Dient als Material, um den Kuku-Rucksack herzustellen, der wiederum für den Kuku-Raketenrucksack von Oongka benötigt wird.",loc:"Käuflich für 85 Kupfer direkt hinter dem Händler an der Lohschmitt-Gerberei (südwestlich des Hernand-Hochlands); weitere Exemplare im Umfeld sind nicht käuflich, lassen sich aber mit angelegter Maske stehlen. Die Packs respawnen, wenn man das Gebiet verlässt und zurückkehrt. Quelle: Game8, TheGamer, GameRant, nerdschalk",miss:false,conf:"high",icons:["cd_assets/items/peddlers-pack-1.webp","cd_assets/items/peddlers-pack-2.webp","cd_assets/items/peddlers-pack-3.webp"]},
  {name:"Pitchfork",cat:"Werkzeug — Sammeln",detail:"Heugabel, mit der Erde zum Bestellen der Felder umgegraben oder Kompost, Stroh und ähnliches Material aufgespießt und bewegt wird. An jeder Schmiede per Refinement aufwertbar.",loc:"Bei jedem Provisioner-Vendor in den Städten von Pywel kaufbar. Quelle: Fextralife (Tools), Gamer Guides, PowerPyx",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_hayfork_0001.webp"},
  {name:"Pororin Fishing Rod",cat:"Werkzeug — Sammeln",detail:"Leichte und dennoch robuste Angelrute aus Spinnenseide, gefertigt von einem Handwerker in der Arboria-Werkstatt nach einer in Pororin überlieferten Technik. Bietet Fishing-Cooldown-Reduction Lv 2 und ist darauf ausgelegt, jeden Fisch zu fangen — die empfohlene Rute für seltene, große und legendäre Fische.",loc:"Freigeschaltet über das Forschungsprojekt 'Secret Tools of Life' (Projekt 2C) im Pororin-Forschungsbaum (Kosten 500 Silber, Dauer 1 Tag 4 Std. — Stand vor Patch 1.18.00; dieser Patch hat am 15.08.2026 die für Forschung benötigte Ressource von Silber auf Camp-Mittel umgestellt, ohne einen Betrag oder Umrechnungskurs zu nennen, der Zahlenwert steht damit unter Vorbehalt); die Rute selbst wird danach über die Produktions-/Dispatch-Option der Arboria-Werkstatt gefertigt. Quelle: Fextralife, Gamer Guides, crimsondb.gg, gaming.tools",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_fishingrod_0002.webp"},
  {name:"Rake",cat:"Werkzeug — Sammeln",detail:"Rechen zum Einebnen der Feld-Erde oder zum Entfernen von Kies; gut geeignet, um den Boden zu glätten. An einer Schmiede per Refinement aufwertbar.",loc:"Bei jedem Provisioner-Vendor in Pywel kaufbar, u. a. im Gemischtwarenladen der ersten Stadt Hernand (die Straße hinunter nahe dem Bluemont-Anwesen, gegenüber den Equipment- und Tailor-Shops), wo auch Angelrute, Schaufel und Schlägel verkauft werden. Quelle: Fextralife, VULKK, gaming.tools",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_rake_0001.webp"},
  {name:"Saw",cat:"Werkzeug — Sammeln",detail:"Ein Schneidwerkzeug mit scharfen Zähnen. Laut Item-Text dient es dazu, Holz auf Maß zu schneiden oder Planken/Bretter zu verarbeiten. Am Schmied per Refinement verbesserbar (sichtbar an goldenen Linien im Item-Bild).",loc:"Allgemeines Holzbearbeitungs-/Sammelwerkzeug; konkreter Vendor/Fundort in den Quellen nicht benannt (Basispreis laut Fextralife 34; kein Eintrag in den questlog-Spieldaten – weder unter den 4.200 Sammel-/Verbrauchs-Items noch unter den 1.878 Ausrüstungsteilen findet sich eine „Säge“). Quelle: Fextralife, crimsondesert.gg, crimsondesert.gaming.tools",miss:false,conf:"medium",icon:"cd_assets/items/saw.webp"},
  {name:"Shovel",cat:"Werkzeug — Sammeln",detail:"Grabwerkzeug zum Ausheben von Erde oder Sand. In-Game-Beschreibung (Fextralife, verbatim): \"A tool for digging up soil or sand. The wide blade can be pressed down with a foot to dig deeper.\" Deckt vergrabene Gegenstände auf (Game8: \"Uncovers Buried Items\") und wird vor allem für das späte Himmelswurz-Graben benötigt. Basis-Angriff 6.",loc:"Kaufbar im Gemischtwarenladen in Hernand (nahe dem Bluemont-Anwesen). Quelle: Fextralife, Game8",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_shovel_0001.webp"},
  {name:"Small Bag",cat:"Werkzeug — Sammeln",detail:"Kein Sammel-/Farmwerkzeug, sondern ein Inventarerweiterungs-Item: schaltet 1 zusätzlichen Inventarplatz frei. Aktiviert sich automatisch beim Erhalt, kein manuelles Ausrüsten nötig. Günstigste Form des permanenten Inventar-Upgrades.",loc:"Nahezu jeder Händler in Pywel führt genau eine Kleine Tasche für ca. 50 Kupfer (kein Nachschub nach dem Kauf); zusätzlich als Belohnung einiger früher Quests/Nebenaufgaben. Quelle: GameSpot, Fextralife, games.gg, thegameswiki",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_inventorybag_0003.webp"},
  {name:"Sotdae of Bond",cat:"Werkzeug — Sammeln",detail:"Vogel-Futterstation (Bird Feeder), das zentrale Mittel zum Zähmen von Vögeln. Wird in der Wildnis platziert (Strg+R bzw. LB+Y); nach dem Befüllen landet ein Vogel und frisst, bis seine Trust-Anzeige 100 erreicht und er sich als Haustier aufnehmen lässt. Verschiedene Umgebungen locken verschiedene Vögel an (Berg: Adler/Sperber; Fluss: Krähe/Sperling). Mit einem Update zusammen mit den Vogel-Haustieren hinzugefügt.",loc:"Belohnung für den Abschnitt 'Das Tor entriegeln' der Fraktionsquest 'Zitternde Wälder' für die Wächter des Pororin-Walds; die Questreihe wird beim Betreten des Dorfes Florindale (südöstlich des Hernand-Hochlands) ausgelöst, wo man per Schlafpfeil betäubt und dem Wächter Arkin vorgestellt wird. Quelle: PC Gamer, Shacknews, KeenGamer, GAMES.GG",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_cd_item_gimmick_birdfeeder_0001.webp"},
  {name:"The Claw",cat:"Werkzeug — Sammeln",detail:"Eine einzigartig benannte Angelrute mit Auto-Fishing-Funktion: Statt manuell einzuholen (rechter Stick), genügt ein einzelner Tastendruck, um gehakte und ermüdete Fische selbsttätig einzuziehen. Macht das ansonsten knifflige Angeln deutlich einfacher.",loc:"Verfügbar ab Abschluss von Kapitel 3. Zwei Wege: Patrigios 'Trust' auf 100 bringen (er erscheint als wandernder Geheimhändler nachts zwischen 0 und 3 Uhr nahe dem Camp am Heulenden Hügel; Vertrauen steigt durch Schenken von ca. 20 Kupferbeuteln, deren Wert egal ist), oder Stehlen von einem Fischer am Steg in Kopfgeldnetz (südwestlich der Spitze der Einsicht, bzw. ein Fischerdorf südlich von Hernand westlich des Stahlgebirges). Quelle: TheGamer, Sportskeeda, GameRant, games.gg",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_fishingrod_0003.webp"},
  {name:"Wooden Pitchfork",cat:"Werkzeug — Sammeln",detail:"Heugabel aus Holz, ein Werkzeug vom Rechen-Typ mit Angriffswert 31. Sie ist leichter als eine Eisengabel und eignet sich gut, um große Mengen Heu zu tragen, kann aber nicht auf hartem Boden eingesetzt werden. Wie alle Werkzeuge nur ein schwacher Notbehelf im Kampf.",loc:"Wird als Farmwerkzeug genutzt und über Werkzeughändler bzw. Feldarbeit bezogen; interner Datenbank-Slug equip_trirake. Quelle: Gamer Guides, crimsondesert.gaming.tools, Fextralife Tools",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_rake_0003.webp"},
  {name:"Wooden Rake",cat:"Werkzeug — Sammeln",detail:"Ein leichter Holzrechen. Laut Item-Text zum Zusammenrechen von Falllaub oder zum Aufräumen von geschnittenem Gras gedacht; nicht geeignet, um tief in den Boden zu graben. Von jedem Charakter nutzbar, am Schmied bis +10 verfeinerbar (Angriff bis 31).",loc:"Bei einem Händler nahe dem Bluemont-Anwesen erhältlich (die Straße hinunter von der zentralen Taverne). Quelle: Fextralife, crimsondesert.gaming.tools, crimsondesert.app, Game8 (Tools-Liste, archive 586917)",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_rake_0002.webp"},
  {name:"Wide Basket",cat:"Werkzeug — Sammeln",detail:"Korb-/Tragewerkzeug aus der Tools-Kategorie, das zum Sammeln und Transportieren von Erntegut bzw. Materialien dient. Es zählt zu den Alltags- und Farmwerkzeugen und richtet im Kampf kaum Schaden an. Eine eigene Statwerttabelle ist in den Quellen nicht hinterlegt.",loc:"Wird wie andere Sammel- und Tragewerkzeuge über Werkzeughändler bezogen und kann bei Schmieden in den Städten verfeinert werden; die genaue Fundstelle ist nicht dokumentiert. Quelle: Fextralife Tools, crimsondb.gg Tools",miss:false,conf:"medium",icon:"cd_assets/items/wide-basket.webp"},
  {name:"Medium Bag",cat:"Werkzeug — Sammeln",detail:"Mittelgroßer Beutel (DE „Mittelgroße Tasche“; Item-Text: „handy room for three extra items“): erweitert das Inventar dauerhaft um 3 Plätze; Grundwert 150 Kupfer. Gehört zur Reihe Kleine Tasche (+1), Mittelgroße Tasche (+3), Große Tasche (+5) und Extragroße Tasche (+10).",loc:"Kein Händlerangebot bei questlog; dafür Belohnung in sehr vielen Missionen (243 Einträge, u. a. „Hand over 5 pieces of fine timber“, „Übergib den Schlägel“, „Übergib den Hecht“, „Übergib 5 Stück Bauholz“). Die 27 Aufträge der Graumähnen geben je einen (siehe Seite Graumähnen-Camp). Quelle: questlog.gg (Item 6002)",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_inventorybag_0004.webp"},
  {name:"Large Bag",cat:"Werkzeug — Sammeln",detail:"Großer Beutel (DE „Große Tasche“; Item-Text: „handy room for five extra items“): erweitert das Inventar dauerhaft um 5 Plätze; Grundwert 250 Kupfer.",loc:"Belohnung der Missionen „Finde Myurdin“, „Überprüfe das Camp“ und „Express your gratitude to Marshal Middler“ (questlog); kein Händler. Quelle: questlog.gg (Item 6005)",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_inventorybag_0005.webp"},
  {name:"Sturdy Broom",cat:"Werkzeug — Sammeln",detail:"Verbesserte, robustere Version des Besens (DE „Robuster Besen“; im Wissenseintrag „Besen“ mit dem normalen Besen zusammengeführt). Besitzt bis zu 3 Abyss-Sockel mit Öffnungskosten von 500 / 1.000 / 2.000 Kupfer (5 / 10 / 20 Silber; questlog). Grundwert 85 Kupfer.",loc:"Bei 16 Händlern für 85 Kupfer kaufbar (u. a. Ronnard, Kiki, Alden, Maidon, Richart, Caden, Berto). Quelle: questlog.gg (Item 1003848), VULKK",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_broom_0002.webp"},
  {name:"Haven for Pets",cat:"Inventar & Camp-Ausbau",detail:"Werkzeug (DE „Haustierheim“), das die Zahl der im Camp haltbaren Haustiere erhöht (Item-Text: „Increases the maximum number of tameable pets“). questlog führt drei Stufen: Kleines Haustierheim (+5), Haustierheim (+10) und Großes Haustierheim (+20). Zusammenhang mit dem 100er-Pet-Limit: siehe Seite Haustiere.",loc:"Small (+5): Belohnung der vier Pet-Missionen „Beginn der gemeinsamen Reise“, „Meisterdompteur“, „Mein verlässlicher Begleiter“, „Bye, My Little Friend“. Haven (+10): Belohnung der Missionen „Hunt and skin the legendary Phoenix“, „Zähme Hyazinthara“, „Zähme den Uhrwerk-Adler“; zusätzlich bei Conrad, Vincent (150 Kupfer) und Erik (300 Kupfer) kaufbar. Large (+20): Belohnung der Mission „Kleiner Begleiter“. Quelle: questlog.gg (Items 1004718, 1004763, 1004764, 1004765, 1004720)",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_pet_slot_expansion_2.webp"},
  {name:"Livestock Capacity Increase",cat:"Inventar & Camp-Ausbau",detail:"Farm-Erweiterung (DE „… Viehzuchtkapazitätserweiterung“), die die Viehkapazität erhöht (Item-Text: „Increases farm livestock capacity by …“). Drei Stufen bei questlog: Small (+3), Medium (+5), Large (+10); Grundwert je 1 Kupfer (kein Verkaufsgegenstand).",loc:"Medium: Belohnung der Entsendung „Camp am Heulenden Hügel: dritte Erweiterung“. Large: Belohnung der Entsendung „Camp am Heulenden Hügel: vierte Erweiterung“; zusätzlich bei Barnaby für 1 Kupfer angeboten. Small: keine Quelle bei questlog. Quelle: questlog.gg (Items 1002755, 1002756, 1002779)",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_inventorybag_0005.webp"},
  {name:"Wells Military Tack",cat:"Reittier-Ausrüstung",detail:"Vierteiliges Reitausrüstungs-Set von Haus Wells (Mount-Tack, getragen vom „Wells' Kavalleriepferd“): Sattel (Wells' Kavallerie-Sattel, DE „Wells' Kavallerie-Sattel“), Steigbügel (Wells' Kavallerie-Steigbügel), Panzerung (Wells' Kavallerie-Rossharnisch, Item-Text: „exceptional defense“, Verteidigung +50 bei +0) und Stirnschutz (Wells' Kavallerie-Rosskopf, Angriff +10). Die Steigbügel gewähren „Health: +0.6 every 1 sec“; der Sattel trägt den Stat 1000000 mit Wert 50 (Bedeutung bei questlog nicht benannt).",loc:"Sattel: Belohnung der Missionen „Return to the temporary camp in Hernand“ und „Besiege Hornspalter“; alle vier Teile sind am Schmied herstellbar (questlog-Rezepte): Rossharnisch 20 Eisenerz + 15 Kupfererz + 5 Dicke Tierhaut; Rosskopf 10 Eisenerz + 5 Kupfererz + 3 Dünnes Fell; Sattel 5 Eisenerz + 10 Dünnes Fell + 5 Dicke Tierhaut + 10 Kurzes Fell; Steigbügel 3 Eisenerz + 2 Kupfererz + 5 Dünnes Fell + 2 Dicke Tierhaut. Quelle: questlog.gg (Items 1001812, 1000587, 1002121, 64382088)",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_r0002_00_horse_saddle_0011.webp"},
  {name:"Kuku Pot",cat:"Werkzeug — Erkundung",detail:"Zwergisches Speicher-/Herstellungsgerät mit 230 Slots, das nur Abyss-Objekte, Maschinenteile und Herstellungskomponenten aufnimmt (keine Waffen, Rüstung oder Nahrung). Basis eines tiefen Progressionssystems: Am Pot lassen sich einzigartige Ausrüstung, Utility-Packs/Rucksäcke, Elementar-Rüstungssets und Komponenten herstellen. Jedes Kuku-Upgrade verlangt einen weiteren Kuku-Eisentopf als Zutat; alle Pots teilen dasselbe Inventar. Verbesserter Kuku-Eisentopf = 1 Kuku-Eisentopf + 1 Abyss-Sphäre, schaltet höhere Rezepte bei Grimnir frei. Stark mit dem Abyss-/Synthese-System verzahnt (Grenzfall — ggf. eigene Seite).",loc:"Erhalt in Kapitel 4 über die Hauptquest \"Geheimnisvoller Topf\": führt zur Kilnden-Werkstatt westlich von Hernand, beim Zwerg Grimnir (zuvor dessen Werkstatt/Kilns reparieren). Quelle: method.gg, GameSpot, VULKK",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_item_kuku_pot_empty.webp"},
  {name:"Visione",cat:"Werkzeug — Erkundung",detail:"Kopfbedeckung mit Erkundungs- und Narrativfunktion statt Kampfschutz: liest Erinnerungsfragment und lässt den Träger Blicke in die Vergangenheit sehen. Zusammen mit der pulsierenden Laterne werden die weltweit verteilten Erinnerungsfragment aufgespürt und abgespielt. Technisch als Kopfbedeckung/Rüstung geführt (Grenzfall zur Seite Rüstungen). Cosmetic-Alternativversionen sollen nach Abschluss der Delesyian-Institute-Forschung erhältlich sein (nicht unabhängig bestätigt).",loc:"Im obersten Stockwerk des Löwenmähne-Wachturms (nach Säubern des Banditenlagers) während Kapitel 2 der Hauptquest \"Unerwartetes Geschenk\" (Teilziel/Memory-Fragment-Strang \"Wo das Licht hinführt\"). Quelle: Fextralife, Game8, PowerPyx",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_phm_00_hel_00_0354_c.webp"},
  {name:"Whistle",cat:"Werkzeug — Mount",detail:"Pfeif-Gadget zum Herbeirufen des Reittiers: per Tastendruck (D-Pad hoch / Taste H) pfeift die Figur, und das Pferd erscheint am nächsten geeigneten Punkt hinter dem Spieler. Frühes Aufwerten der Pfeife vergrößert die Rufreichweite und macht sie zu einer der zentralen Erkundungshilfen, um Pywel schnell zu durchqueren. Funktion/Feature, kein klassisches Inventar-Item (Grenzfall).",loc:"Standardfähigkeit ab Spielbeginn; Reichweiten-Upgrades über Spielfortschritt/Stall. Quelle: Shacknews, esports.gg",miss:false,conf:"medium"},
  {name:"Arrow",cat:"Munition",detail:"Standard-Pfeilmunition für Bögen, um Ziele aus der Distanz in Jagd oder Kampf zu treffen. Grundmunition ohne Sondereffekt.",loc:"Equipment-/Waffenhändler, Schmiede-Herstellung, Gegner-Loot; basaler Resupply u. a. an der Belagerungsrüstkammer von Calphade. Quelle: Fextralife Blaupausen für Kugeln, crimsondb.gg",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_phm_04_arw_0001.webp"},
  {name:"Blitz Arrow (Lightning Arrow)",cat:"Munition",detail:"Pfeil, um Ziele aus der Ferne zu treffen und Blitz-/Blitzschaden zuzufügen.",loc:"Belohnung der Mission „Sternbild Kamel“ (Quest „Sternbilder“; im questlog-Item 1001315 als Schritt „Beobachte Sternbild Kamel“ geführt, dort unter Sammelgegenständen statt unter Projektilen); Slug lightning_arrow / blitz-arrow. Quelle: questlog.gg, crimsondesert.gaming.tools, crimsondb.gg",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_phm_04_arw_0018.webp"},
  {name:"Bullet",cat:"Munition",detail:"Metallkugel, mit Schwarzpulver verschossen; jeder Schuss verbraucht viel Pulver, daher seltener nutzbar als Pfeile. Munition für Pistole, Muskete und Schrotflinte.",loc:"Bei Händlern für 3 Kupfer kaufbar (questlog: zahlreiche Händler, z. B. Rhett, Temir, Kathor); Craft am Blacksmith aus 2 Eisenerz + 4 Schießpulver; Loot von Schützen, Versorgungskisten in Pywel. Quelle: questlog.gg, Fextralife Bullet, crimsondb.gg",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0254_dropitem_bullet_0001.webp"},
  {name:"Explosive Arrow (Bomb Arrow)",cat:"Munition",detail:"Pfeil mit Sprengvorrichtung, der bei Aufprall explodiert; deutlicher Flächenschaden gegen Gegnergruppen, schwache Strukturen oder als harter Einzeltreffer.",loc:"Freischaltung über die Demeniss-Armory-Dispatch-Mission (alle 12 Ingame-Stunden), zusätzlich bei Back-Alley-Händlern kaufbar. Quelle: itemlevel.net, Sportskeeda",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_phm_04_arw_0007.webp"},
  {name:"Ice Arrow (Chill Arrow)",cat:"Munition",detail:"Pfeil mit Eis-/Frost-Element; trifft Ziele aus der Distanz und fügt Eisschaden zu. Ingame-/Datenbankname lautet \"Kältepfeil\" (Slug ice_arrow).",loc:"Belohnung der Mission „Sternbild Elefant“ (Quest „Sternbilder“; im questlog-Item 1001314 „Kältepfeil“ als Schritt „Beobachte Sternbild Elefant“ geführt, dort unter Sammelgegenständen); Slug ice_arrow / chill-arrow. Quelle: questlog.gg, crimsondesert.gaming.tools, crimsondb.gg",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_phm_04_arw_0016.webp"},
  {name:"Poison Arrow",cat:"Munition",detail:"Pfeil, der beim Treffer Gift (Schaden über Zeit) auslöst; gut zum Anstacken von Dauerschaden, besonders gegen zähe Gegner.",loc:"Rezept im Hinterhofladen von Festung Perwin kaufbar; Craft aus 1 Pfeil + 1 Giftflasche (Gift u. a. beim Häuten von Waranen/Monitor Lizards). Quelle: itemlevel.net, Sportskeeda",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_phm_04_arw_0008.webp"},
  {name:"Replenishing Bullets",cat:"Munition",detail:"Schwarzpulver-Kugeln, die sich durch fortschrittliche Technik mit der Zeit selbst nachfüllen (begrenzter Vorrat von ca. 40, der langsam regeneriert); Munition für Pistole, Muskete und Schrotflinte.",loc:"Freischaltung über die Keep-Facility-Forschung im Forschungsinstitut der Festung von Tauhafen, Ausbau via Electric Tool Design u. a. Quelle: crimsondb.gg, crimsondesert.gaming.tools",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0254_dropitem_bullet_0001_infinite.webp"},
  {name:"Sleep Arrow",cat:"Munition",detail:"Pfeil mit beruhigungsmittelbeschichteter Spitze; das getroffene Ziel fällt in Schlaf/Bewusstlosigkeit und schafft ein taktisches Fenster für Folgeangriffe.",loc:"Beim Stamm in Longleaf Village: Langzweig-Stamm-Rätsel lösen und Vertrauen aufbauen, danach im Versorgungsdepot abrufbar. Quelle: Sportskeeda, itemlevel.net",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_phm_04_arw_0014.webp"},
  {name:"Small Cannonball",cat:"Munition",detail:"Kleinkalibrige, leicht transportierbare Kanonenkugel, dicht mit Schwarzpulver gepackt; löst beim Aufprall eine Explosion mit Schockwelle aus, die nahe Gegner wegschleudert und Formationen zerbricht. Munition für Hand Kanonen.",loc:"Craft an der Schmiede aus 10 Eisenerz + 10 Schießpulver (Rezept). Quelle: Fextralife (Small Cannon Ball Recipe), crimsondesert.gaming.tools",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0254_dropitem_cannonball_0001.webp"},
  {name:"Stub Arrow (Pyeonjeon Arrow)",cat:"Munition",detail:"Spezialpfeil in kürzerer, schlankerer Form als Standardpfeile; liefert Durchschlags- und Zerstörungskraft, die gewöhnliche Pfeile übertrifft.",loc:"In Datenbanken geführt (Slug pyeonjeon_arrow / stub-arrow). Quelle: crimsondesert.gaming.tools, crimsondesert.gg",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_phm_04_arw_0020.webp"},
  {name:"Whistling Arrow (Hyosi Arrow)",cat:"Munition",detail:"Signalpfeil zum Herbeirufen verbündeter Unterstützung; auf den Boden geschossen, ruft er ein Artillerie-Sperrfeuer auf das Zielgebiet. Die eigene Durchschlagskraft ist kaum höher als bei einem normalen Pfeil.",loc:"In Datenbanken geführt (Slug hyosi_arrow / whistling-arrow). Quelle: crimsondesert.gaming.tools, crimsondb.gg",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_phm_04_arw_0003.webp"},
  {name:"Crude Bismuth Cannonball",cat:"Munition",detail:"Kanonenkugel-Munition aus Bismut, die einfache (rohe) Unterstufe der Bismut-Geschosslinie. Sie wird für tragbare Kanonen bzw. die Bismut-Kanone verwendet und verfolgt laut Item-Text das Ziel (questlog EN: „Fires a bismuth cannon shell that pursues the enemy“, DE: „… die das Ziel verfolgt“) – wie die Itano-Linie. Die Guide-Angabe „flächiger Explosionsschaden“ steht nicht im Spieltext. Höherwertige Varianten ohne den 'Crude'-Zusatz haben bessere Werte; die Reihe umfasst u. a. auch Crude Itano und Itanokanonenkugel.",loc:"Laut questlog Zufallsdrop bei Demenessische Wache und Belohnung der Dispatch-Mission „St. Halssius's House of Healing Bridge Construction“; ein Herstellungsrezept für diese Kugel führt questlog nicht, die Guide-Angabe „über Bismut hergestellt“ ist damit nicht bestätigt (Bismut ist laut Guides erst nach Freischalten einer Blitzfähigkeit abbaubar: Damiane Kap. 3 bzw. Kliffs Blitzbogen Kap. 4). Quelle: questlog.gg (1000018), Gamer Guides (Projektilliste), thegameswiki Kanonen-Guide, crimsondb.gg Ammunition",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0254_dropitem_cannonball_0001.webp"},
  {name:"Dark Magic Bullet",cat:"Munition",detail:"Wurf-Magiekugel mit Dunkelheits-Element (questlog: „Magiewurfkugel - Dunkelheit“, DE „Dunkelmagiekugel“); Grundwert 10 Kupfer. Weitere Wirkung nicht erfasst.",loc:"Belohnung der Mission „Talk to the witch at the Sanctum of Oblation“ (Quest Hexe der Demut; Lyselia-Strang), dort zusammen mit der Alchemieformel: Apollonias überragendes Elixier und einem Generalschlüssel. Quelle: questlog.gg (Item 1000416), crimsondb.gg",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0254_dropitem_bullet_0001.webp"},
  {name:"Disruptor Cannonball",cat:"Munition",detail:"Anti-Maschinen-Kanonenkugel, die auf Stör-/Unterbrechungsnutzen statt auf rohen Schaden ausgelegt ist: Trifft sie einen mechanischen Gegner, unterbricht sie dessen Energiefluss und setzt ihn vorübergehend außer Gefecht (questlog; Einsatz mit dem Blaster). Sie wird empfohlen für schwierige Gefechte und Bosskämpfe aufzusparen. Bezug laut questlog: Belohnung der Mission „Wahre Stärke“ (Quest „Sechs nachdenkliche Statuen und der böse Geist“; im Item-Datensatz als Schritt „Geleite T'rukan auf den rechten Pfad“ geführt).",loc:"Einmalige Missionsbelohnung („Wahre Stärke“, Quest „Sechs nachdenkliche Statuen und der böse Geist“); für diese Kugel führt questlog weder Händler noch Drop noch Rezept – die Guide-Angabe „Bezug über Herstellung bzw. Munitionsvorräte“ ist nicht belegt. Quelle: questlog.gg (Item 1001773), thegameswiki Kanonen-Guide, crimsondb.gg Ammunition",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_phm_10_bomb_0010.webp"},
  {name:"Fire Arrow",cat:"Munition",detail:"Pfeil mit Feuerelement (Feuerschaden aus der Distanz). Item-Text: 'can also deal fire damage'. Das Item existiert in den Spieldaten (questlog 1001316), allerdings in der Kategorie collectibles/goods (Grundwert 2 Kupfer) und nicht als Munition (projectiles) wie Bullet; einzelne Guides sagen dagegen, es gebe keine Feuerpfeil-Munition und Feuerschaden entstehe nur durch Entzünden eines normalen Pfeils an Lagerfeuer/Fackel. Ob das Item als normale Munition nutzbar ist, ist nicht belegt.",loc:"Questlog nennt als Herkunft die Mission 'Observe the goblin constellation'; Listeneintrag auch bei crimsondesert.gaming.tools (fire_arrow); alternativ Entzünden normaler Pfeile an Feuerquellen. Quelle: questlog.gg (Item 1001316), crimsondesert.gaming.tools, Sportskeeda",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_phm_04_arw_0012.webp"},
  {name:"Itano Cannonball",cat:"Munition",detail:"Kanonenkugel, die einen spezialisierten Sprengsatz freisetzt, der mit erratischen Hochgeschwindigkeits-Manövern Gegner aufspürt (zielsuchend/Homing). Munition für Hand Kanonen.",loc:"Bezugsquelle bei questlog nicht erfasst (Item 1001935 ohne Händler, Drop oder Rezept); die einfache Unterstufe „Grobe Itano-Kanonenkugel“ ist Belohnung der Entsendung „Brückenbaukunst im Sklavinnenlager von Roccas Hügel“. Quelle: questlog.gg, crimsondb.gg (itano-cannonball)",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0254_dropitem_cannonball_0001.webp"},
  {name:"Magic Bullet",cat:"Munition",detail:"Wurf-Magiekugel mit Wind-Element (questlog: „Magiewurfkugel - Wind“, DE „Magiekugel“); Grundwert 10 Kupfer. Weitere Wirkung nicht erfasst.",loc:"Bezugsquelle bei questlog nicht erfasst (kein Händler, Drop oder Missionsbelohnung). Quelle: questlog.gg (Item 1001862), crimsondb.gg",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0254_dropitem_bullet_0001.webp"},
  {name:"Fire Magic Bullet",cat:"Munition",detail:"Wurf-Magiekugel mit Element Feuer (questlog: „Magiewurfkugel - Feuer“, DE „Feuermagiekugel“); Grundwert 10 Kupfer. Weitere Wirkung nicht erfasst; Gegenstück zu Magiekugel (Wind) und Dunkelmagiekugel.",loc:"Keine Bezugsquelle bei questlog. Quelle: questlog.gg (Item 1000152)",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0254_dropitem_bullet_0001.webp"},
  {name:"Water Magic Bullet",cat:"Munition",detail:"Wurf-Magiekugel mit Element Wasser (questlog: „Magiewurfkugel - Wasser“, DE „Wassermagiekugel“); Grundwert 10 Kupfer. Weitere Wirkung nicht erfasst; Gegenstück zu Magiekugel (Wind) und Dunkelmagiekugel.",loc:"Kauf bei Conrad und Edmon für je 10 Kupfer (questlog). Quelle: questlog.gg (Item 1000153)",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0254_dropitem_bullet_0001.webp"},
  {name:"Ice Magic Bullet",cat:"Munition",detail:"Wurf-Magiekugel mit Element Eis (questlog: „Magiewurfkugel - Eis“, DE „Eismagiekugel“); Grundwert 10 Kupfer. Weitere Wirkung nicht erfasst; Gegenstück zu Magiekugel (Wind) und Dunkelmagiekugel.",loc:"Keine Bezugsquelle bei questlog. Quelle: questlog.gg (Item 1000399)",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0254_dropitem_bullet_0001.webp"},
  {name:"Lightning Magic Bullet",cat:"Munition",detail:"Wurf-Magiekugel mit Element Donner (questlog: „Magiewurfkugel - Donner“, DE „Donnermagiekugel“); Grundwert 10 Kupfer. Weitere Wirkung nicht erfasst; Gegenstück zu Magiekugel (Wind) und Dunkelmagiekugel.",loc:"Keine Bezugsquelle bei questlog. Quelle: questlog.gg (Item 1000429)",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0254_dropitem_bullet_0001.webp"},
  {name:"Dark Ice Spear Magic Bullet",cat:"Munition",detail:"Wurf-Magiekugel mit Element Dunkler Eisspeer (questlog: „Magic Bullet for Throwing - Dark Ice Spear“, DE „Dunkler Eisspeer“-Magiekugel); Grundwert 10 Kupfer. Weitere Wirkung nicht erfasst; Gegenstück zu Magiekugel (Wind) und Dunkelmagiekugel.",loc:"Keine Bezugsquelle bei questlog. Quelle: questlog.gg (Item 1000482)",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0254_dropitem_bullet_0001.webp"},
  {name:"Light Fist Magic Bullet",cat:"Munition",detail:"Wurf-Magiekugel mit Element Licht (questlog-Itemname „Lichtfaust-Magiekugel“, Item-Text „Magiewurfkugel - Licht“, DE „Lichtfaust-Magiekugel“); Grundwert 10 Kupfer. Weitere Wirkung nicht erfasst; Gegenstück zu Magiekugel (Wind) und Dunkelmagiekugel.",loc:"Keine Bezugsquelle bei questlog. Quelle: questlog.gg (Item 1001937)",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0254_dropitem_bullet_0001.webp"},
  {name:"Snow Magic Bullet",cat:"Munition",detail:"Wurf-Magiekugel mit Element Schnee (questlog: „Magiewurfkugel - Schnee“, DE „Schnee-Magiekugel“); Grundwert 10 Kupfer. Weitere Wirkung nicht erfasst; Gegenstück zu Magiekugel (Wind) und Dunkelmagiekugel.",loc:"Belohnung der Mission „Talk to the witch at the Sanctum of Veneration“ (Quest Hexe der Demut; questlog). Quelle: questlog.gg (Item 1001939)",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0254_dropitem_bullet_0001.webp"},
  {name:"Mine Spider Cannonball",cat:"Munition",detail:"Spezial-Kanonenkugel mit Zusatznutzen über reinen Schaden hinaus; ebenfalls für schwierige Kämpfe und Bosse gedacht. Die Kugel beschwört eine Minenspinne, die Gegner aufspürt, eine starke Explosion auslöst und alle Gegner in der Nähe wegschleudert (questlog).",loc:"Bezugsquelle nicht belegt: questlog führt für die Kugel weder Händler, Drop, Missionsbelohnung noch Rezept; die Guide-Angabe „Herstellung bzw. Munitionsvorräte“ ist durch die Spieldaten nicht gedeckt. Quelle: questlog.gg (Item 1001884), thegameswiki Kanonen-Guide, crimsondb.gg Ammunition",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0254_dropitem_cannonball_0001.webp"},
  {name:"Replenishing Arrows (Quiver)",cat:"Munition",detail:"Pfeil-Munition mit verbessertem Aufbau; laut Item-Text (questlog) lassen sich zerbrochene Pfeile wiederverwenden ('allows broken arrows to be reused'). Guides beschreiben es als Köcher-/Versorgungs-Item, das den Pfeilvorrat mit der Zeit selbsttätig nachfüllt (Slug quiver bei crimsondesert.gaming.tools); der Item-Text nennt das – anders als bei den 'Stetiger Kugelnachschub' ('self-replenish over time') – nicht.",loc:"Questlog (Item 1002557, DE 'Pfeil: Stetiger Nachschub') nennt als Herkunft die Mission 'Stelle den Abyss wieder her' (Quest 'Abyss'); thematisch verwandt mit den \"Endlose Pfeile\"-Abyss-Gear. Quelle: questlog.gg, crimsondesert.gaming.tools, TheGamer",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_phm_04_arw_0001_infinite.webp"},
  {name:"Bundle of Arrows",cat:"Munition",detail:"Pfeilbündel (DE „Pfeilbündel“). Item-Text: „A bundle of 30 arrows for combat, proving invaluable when arrows are in short supply“. questlog führt zwei Stufen: 30 Pfeile (Item 50057, Grundwert 50 Kupfer) und 5 bis 15 Pfeile (Item 1000224, Grundwert 15 Kupfer).",loc:"30er-Bündel: Kauf beim Trugbild-Händler für 50 Kupfer; Drop (je 4 Stück, 15 % Chance) u. a. bei Demenessische Wache, Calphadischer Wächter, Wells' Legionär, Beighen-Milizionär und Hernand-Wache. 5–15er-Bündel: Drop (je 1 Stück, 10 % Chance) u. a. bei Blut-Bandit, Bandit, Blendpfeil und Wells' Legionär. Quelle: questlog.gg (Items 50057, 1000224)",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0254_dropitem_multiarrow_0001.webp"},
  {name:"Bundle of Bullets",cat:"Munition",detail:"Kugelbündel (DE „Kugelpaket“). Item-Text: „A bundle of 20 bullets for combat, proving invaluable when bullets are in short supply“. questlog führt zwei Stufen: 20 Kugeln (Item 1000026, Grundwert 50 Kupfer) und 5 bis 15 Kugeln (Item 1003653, Grundwert 25 Kupfer).",loc:"20er-Bündel: Kauf beim Trugbild-Händler für 50 Kupfer; Drop (je 4 Stück, 15 %) bei Wachen wie Demenessische Wache, Calphadischer Wächter und Wells' Legionär; Belohnung der Entsendung „Bau einer Gedenkhalle für das Königliche Grab“. 5–15er-Bündel: Drop (je 1 Stück, 15 %) u. a. bei Helm, Gerechter Inquisitor, Hernand-Wache und Wyvernflamme. Quelle: questlog.gg (Items 1000026, 1003653)",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0254_dropitem_bullet_0001.webp"},
  {name:"Bundle of Cannonballs",cat:"Munition",detail:"Bündel kleiner Kanonenkugeln (DE „Kanonenkugelpaket“). Item-Text: „A bundle of 10 small cannonballs“. questlog führt zwei Stufen: 10 Kugeln (Item 1000063, Grundwert 130 Kupfer) und 2 bis 6 Kugeln (Item 1003654, Grundwert 65 Kupfer).",loc:"10er-Bündel: Kauf beim Trugbild-Händler für 130 Kupfer; Drop (je 4 Stück, 10 %) bei Wachen wie Demenessische Wache und Wells' Legionär; Belohnung der Mission „Stelle den Abyss wieder her“. 2–6er-Bündel: Drop (je 1 Stück, 20 %) bei Clan der Eisenflammen-Ork, Wyvernflamme, Wells' Legionär und Faceless. Quelle: questlog.gg (Items 1000063, 1003654)",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0254_dropitem_cannonball_0001.webp"},
  {name:"Buckshot Bullet",cat:"Munition",detail:"Schrotmunition (DE „Schrotkugel“): viele kleine Metallgeschosse, die beim Abfeuern weit streuen; stark gegen gruppierte oder schnelle Gegner auf kurze Distanz. Nur mit ausgerüsteter Schrotflinte nutzbar. Grundwert 3 Kupfer.",loc:"Belohnung der Mission „Find a means of escape from the castle's underground“; für diese Kugel führt questlog keinen Händler. Quelle: questlog.gg (Item 1001320)",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0254_dropitem_bullet_0001.webp"},
  {name:"Silver Bullet",cat:"Munition",detail:"Glänzende Silberkugel (DE „Silberkugel“); der Item-Text nennt keinen Sondereffekt. Grundwert 3 Kupfer.",loc:"Drop (25 % Chance) bei Goblin-Fundamentalisten (51 Einträge) und beim Hauptmann des Angriffstrupps der Höllenhunde. Quelle: questlog.gg (Item 1002125)",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0254_dropitem_bullet_0001.webp"},
  {name:"Replenishing Cannonballs",cat:"Munition",detail:"Kleinkalibrige Kanonenkugeln (DE „Kontinuierliche Versorgung mit Sprengkanonen“), die sich laut Item-Text durch fortschrittliche Technik mit der Zeit selbst nachfüllen; Munition für den Blaster. Gegenstück zu Stetiger Kugelnachschub und Pfeil: Stetiger Nachschub.",loc:"questlog führt weder Händler noch Drop, Rezept oder Missionsbelohnung; Bezugsquelle nicht erfasst. Quelle: questlog.gg (Item 1003752)",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0254_dropitem_cannonball_0001_infinite.webp"},
  {name:"Crude Itano Cannonball",cat:"Munition",detail:"Einfache Unterstufe der Itano-Kanonenkugel (DE „Grobe Itano-Kanonenkugel“). Item-Text: „Releases a specialized explosive that seeks out enemies with erratic high speed maneuvers“ (DE: „… die den Feind verfolgt“). Grundwert 15 Kupfer.",loc:"Belohnung der Entsendung „Brückenbaukunst im Sklavinnenlager von Roccas Hügel“; sonst keine Bezugsquelle bei questlog. Quelle: questlog.gg (Item 1000017)",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0254_dropitem_cannonball_0001.webp"},
  {name:"Dart",cat:"Munition",detail:"Wurfpfeil (DE „Wurfpfeil“); der Item-Text lautet lediglich „A dart for throwing“. Grundwert 7 Kupfer.",loc:"Bezugsquelle bei questlog nicht erfasst. Quelle: questlog.gg (Item 1001845)",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0254_dropitem_bullet_0001.webp"},
  {name:"Shiny Rock",cat:"Munition",detail:"Leuchtender Stein (DE „Glänzender Stein“), der geworfen werden kann und dunkle Bereiche beleuchtet. Grundwert 1 Kupfer.",loc:"Drop (50 % Chance) bei der Wache vom Haus der Heilung; Belohnung der Missionen „Return to the comrades gathered at the camp“ und „Sprich mit dem Händler“. Quelle: questlog.gg (Item 1000522)",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_gimmick_shinystone_02.webp"},
  {name:"Shineberry",cat:"Munition",detail:"Von selbst sanft leuchtende Frucht (DE „Leuchtfrucht“): als Wurfgeschoss gegen Gegner oder Ziele nutzbar und hilft, Objekte auch an dunklen Orten zu finden. Grundwert 50 Kupfer.",loc:"Fester Drop (100 %) bei Moosrückenkrebsen (u. a. Kleiner, Mittlerer und Großer Moosrückenkrebs, Mittlerer Florarückenkrebs, Abyss-Moosrückenkrebs); Belohnung der Mission „Besiege die Königin der Bismut-Erzrückenkrebse“. Quelle: questlog.gg (Item 1001777)",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_glowfruit_01.webp"},
  {name:"Fire Bomb",cat:"Verbrauchsgegenstand — Wurf/Kampf",detail:"Wurfwaffe, die mit Schwarzpulver eine kraftvolle Explosion und Feuer erzeugt; nach dem Zünden auf ein Ziel werfbar oder am Boden als Falle platzierbar.",loc:"Craftbar über Alchemie/Engineering oder bei Spezialhändlern kaufbar; Datenbank-Slug fire_bomb. Quelle: crimsondesert.gaming.tools, crimsondesert.gg",miss:false,conf:"high",icon:"cd_assets/items/fire-bomb.webp"},
  {name:"Smoke Bomb",cat:"Verbrauchsgegenstand — Wurf/Kampf",detail:"Umhüllt den Explosionspunkt mit Rauch und bricht die Sichtlinie der Gegner; Kernwerkzeug für Stealth (Entkommen/Verschwinden), gekoppelt an die Storm-Veil-Fähigkeit.",loc:"Fähigkeit/Abruf wird laut Guides über den Hauptstrang ab Abschluss von Kapitel 8 (Uhrwerkspitze / Abyss) freigeschaltet; das Item selbst ist laut questlog bei Händlern für 70 Kupfer kaufbar (z. B. Bran, Leonard, Marin; Item 1000803) und Belohnung einer Abyss-Mission 'Stelle den Abyss wieder her'. Datenbank-Slug smoke_bomb. Quelle: questlog.gg, crimsondesert.gaming.tools, GamerGuides",miss:false,conf:"high",icon:"cd_assets/items/smoke-bomb.webp"},
  {name:"Vine Bomb",cat:"Verbrauchsgegenstand — Wurf/Kampf",detail:"Wurfbombe. Beim Explodieren werden die im Wirkungsbereich erfassten Gegner in Ranken gefangen und dadurch bewegungsunfähig gemacht (Fang-/Verwurzelungseffekt statt reinem Schaden).",loc:"Eigene Datenbankseite sowie Munitionslisten; Effekt mehrfach beschrieben. Quelle: crimsondb.gg, questlog.gg, crimsondesert.gg",miss:false,conf:"high",icon:"cd_assets/items/smoke-bomb.webp"},
  {name:"Crow Bomb",cat:"Verbrauchsgegenstand — Wurf/Kampf",detail:"Wurfbombe, die bei der Explosion einen Schwarm Krähen beschwört. Die Krähen greifen nahe Gegner an.",loc:"Munitionsdatenbanken; die aktuelle Itembeschreibung bestätigt die Krähenwirkung. Quelle: questlog.gg, crimsondb.gg",miss:false,conf:"high"},
  {name:"Water Bomb",cat:"Verbrauchsgegenstand — Wurf/Kampf",detail:"Wurfbombe, die am Aufprallpunkt Wassertropfen erzeugt und getroffene Gegner darin einschließt.",loc:"Munitionsdatenbanken; die aktuelle Itembeschreibung bestätigt den Fangeffekt. Quelle: questlog.gg, crimsondb.gg",miss:false,conf:"high"},
  {name:"Oil Canister",cat:"Verbrauchsgegenstand — Wurf/Kampf",detail:"Ölfass (DE „Ölfass“): nach dem Wurf breitet sich Öl rund um das Ziel aus – wirksam gegen Gegnergruppen; im Nahbereich eingesetzt gefährdet es den Werfer selbst (Item-Text). Grundwert 30 Kupfer.",loc:"Bezugsquelle bei questlog nicht erfasst. Quelle: questlog.gg (Item 52007)",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_oil_barrel.webp"},
  {name:"Goldleaf Censer",cat:"Verbrauchsgegenstand — Wurf/Kampf",detail:"Auf den ersten Blick ein gewöhnlicher goldener Krug (DE „Blattgold-Räuchergefäß“), aus dem nach dem Entzünden unheilvoller roter Rauch quillt. Grundwert 15 Kupfer; ein weiterer Nutzen ist im Item-Text nicht genannt.",loc:"Bezugsquelle bei questlog nicht erfasst. Quelle: questlog.gg (Item 52006)",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_gimmick_item_goblinpot.webp"},
  {name:"Sticky Bomb",cat:"Verbrauchsgegenstand — Wurf/Kampf",detail:"Bombe, die an Oberflächen haftet (DE „Haftbombe“); laut Item-Text vielseitig für kreative Taktiken. Grundwert 1 Kupfer.",loc:"Bezugsquelle bei questlog nicht erfasst. Quelle: questlog.gg (Item 53032)",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_battle_sticky_bomb.webp"},
  {name:"Time Bomb",cat:"Verbrauchsgegenstand — Wurf/Kampf",detail:"Bombe, die nach einer festgelegten Zeit explodiert (DE „Zeitbombe“); nützlich, wenn präzises Timing nötig ist. Grundwert 1 Kupfer.",loc:"Bezugsquelle bei questlog nicht erfasst. Quelle: questlog.gg (Item 53034)",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_gimmick_item_quest_sticky_bomb_01.webp"},
  {name:"Sticky Flower Bomb",cat:"Verbrauchsgegenstand — Wurf/Kampf",detail:"Blumenförmige Haftbombe mit auffälligem Design (DE „Klebrige Blumenbombe“). Grundwert 1 Kupfer; weitere Eigenschaften sind im Item-Text nicht genannt.",loc:"Bezugsquelle bei questlog nicht erfasst. Quelle: questlog.gg (Item 1000089)",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_gimmick_item_quest_sticky_flower_bomb.webp"},
  {name:"Deployable Explosive",cat:"Verbrauchsgegenstand — Wurf/Kampf",detail:"Taktischer Sprengstoff (DE „Installierbare Bombe“), der am Boden oder an einer Struktur befestigt und dann gezündet wird: Hinterhalt entlang der erwarteten Feindroute oder Zerstörung befestigter Ziele (Item-Text). Grundwert 1 Kupfer.",loc:"Bezugsquelle bei questlog nicht erfasst. Quelle: questlog.gg (Item 1000123)",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_battle_sticky_bomb.webp"},
  {name:"Antidote",cat:"Verbrauchsgegenstand — Heilung/Status",detail:"Verbrauchsgegenstand, der den Gift-Status (Gift-DoT) heilt. Weder in den Spieldaten von questlog noch auf Fextralife findet sich ein Item namens 'Antidote' oder ein anderer Verbrauchsgegenstand, der Gift heilt; Existenz und Wirkung sind unbestätigt (Prüfung 03.10.2026).",loc:"Datenbank-/Listeneintrag (Game8, crimsondb.gg). Quelle: Game8 List of All Items, crimsondb.gg",miss:false,conf:"low"},
  {name:"Abyss Artifact",cat:"Währung & Progression",detail:"Kern-Progressionswährung, ersetzt das klassische XP-Leveln. Ein reguläres Artefakt gewährt sofort 1 Fähigkeitspunkt für den Skill-Tree oder für Kernwerte (Health, Geist, Ausdauer). Ab Equipment-Refinement +5 werden zusätzlich reguläre Abyss-Artefakte zum Aufwerten von Waffen/Rüstung benötigt; in Gear investierte Artefakte sind nicht rückholbar (auch nicht per Faded). Von egamersworld, esports.gg und GamesGG bestätigt.",loc:"Welt-Drops, Bosse, Erkundung, Belohnung aus Versiegelten Abyss-Artefakten. Käuflich laut questlog für 2850 Kupfer bei den Hexen Areciel, Elowen, Bari und Lyselia sowie bei Patrigio; Jasper verkauft es gegen 200 Marni-Münze. Quelle: questlog.gg (Item 75001), egamersworld, esports.gg, GamesGG",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_abyss_artifact_a_0001.webp"},
  {name:"Camp Funds",cat:"Währung & Progression",detail:"Gemeinschaftswährung getrennt vom persönlichen Silber, finanziert das Graumähnen-Camp: Dispatch-Missionen, Ausbauten und das Pailune-Wiederaufbauprojekt. Verdient durch Spende an Carl (Lagervorräte-Verwaltung) am Heulenden Hügel via 'Manage Provisions' > 'Camp Provisions' > 'Donate Funds' (persönliches Silber oder laut älteren Guides Gold Bars; seit Patch 2.01.00 vom 04.09.2026 bringt gespendetes Silber die zehnfache Menge Camp-Mittel; ob Gold Bars danach noch am schnellsten sind, ist offen, questlog nennt als Quellen nur Silberspenden und Entsendungen) oder durch Graumähnen-Dispatch auf 'Schild'/Security-Missionen bei Ross (Dispatch-Koordinator), die Camp-Mittel geben und wiederholbar sind.",loc:"Spende an Carl (Heulender Hügel) oder Dispatch-Belohnungen über Ross. Quelle: GameRant, Game8, gfinityesports",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0056_coin_0004.webp"},
  {name:"Coin Purse",cat:"Währung & Progression",detail:"Von Gegnern gedroppte Geldbörse (Sammelbegriff; questlog führt die Beutel einzeln: Paltry/Light/Modest/Full Copper Pouch, Modest/Full/Overflowing/Wayfarer's Silver Pouch). Kein Verkaufs-Item, sondern direkt aus dem Inventar zu öffnen und sofort in Silber umgewandelt. Quelle: PowerPyx.",loc:"Gegner-Loot. Quelle: PowerPyx.",miss:false,conf:"medium",icon:"cd_assets/items/coin-purse.webp"},
  {name:"Contribution Point",cat:"Währung & Progression",detail:"Regional gebundene Fraktions-Währung (getrennt von der globalen Reputation); in den Spieldaten je Region als 'Hernand-, Demeniss-, Pailune-, Delesyia-, Tashkalp-Beitrag' bzw. 'Graumähnen-Beitrag' geführt (EN: Hernandian/Demenissian/Pailunese/Delesyian/Tashkalp/Graumähnen-Beitrag). Beitrag-XP stammen aus Fraktionsquests, Notice-Board-Requests, Bounties und guten Taten (Flüchtlinge befreien, Bettlern Münzen geben); das Befreien von Festungen gibt den größten Einzel-Schub. Pro Level 1 Contribution Point. Ausgegeben in regionalen Contribution Shops für exklusive Gear, Accessoires, Rossharnische, Banner (als Zweihandwaffe nutzbar) und Camp-Worker. Gekaufte Items sind zum gleichen Punktpreis rückverkaufbar. Diebstahl senkt den Beitrag.",loc:"Fraktionsquests/Bounties je Region; Ausgabe in regionalen Contribution Shops (z. B. Haldwin in der Burg Hernand). Quelle: GameRant, PC Gamer, Game8",miss:false,conf:"high"},
  {name:"Copper Coin",cat:"Währung & Progression",detail:"Kleinste Währungseinheit und häufigster Gegner-Drop, auch aus Beute-Beuteln (Copper/Silver Pouch). Für kleine Käufe wie Schlüssel (z.B. 30 Kupfer beim Back Alley Merchant). Umrechnung: 100 Kupfer = 1 Silber. Im Spiel als 'Kupfer' geführt (questlog Item 1). Mehrfach bestätigt (Method.gg, PowerPyx, thegameswiki).",loc:"Gegner-Drops, Beutel, Erkundung in ganz Pywel. Quelle: Method.gg, PowerPyx, thegameswiki",miss:false,conf:"high",icon:"cd_assets/items/copper-coin.webp"},
  {name:"Crude Gold Bar",cat:"Währung & Progression",detail:"Roh-Goldbarren als sammelbare Verkaufswährung (Patch 1.05.00). An Händler in Pywel ~5 Silber/Stück; Wolfram (Fischshop, Vellua) zahlt 7,90 Silber. In großen Clustern (100-200 Stück) an einzelnen Fundorten farmbar. Quelle: PC Gamer / Game8.",loc:"Sammelbare Cluster über Pywel verteilt; Verkauf an Händler/Wolfram. Quelle: PC Gamer.",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_in_dpfo_goldbar_01.webp"},
  {name:"Faded Abyss Artifact",cat:"Währung & Progression",detail:"Respec-Währung: Der Verbrauch setzt den kompletten Skill-Tree zurück und gibt alle in Fähigkeiten investierten Punkte zur Neuverteilung frei; laut Item-Text lassen sich auch in Ausdauer, Geist und Health investierte Abyss-Kräfte zurückholen. Setzt jedoch KEINE in Gear-Refinement investierten Artefakte zurück. Wichtig: betrifft alle drei spielbaren Charaktere (Kliff, Damiane, Oongka) gleichzeitig, da sie denselben Artefakt-Pool teilen. Laut VULKK existiert eine Methode, faktisch unbegrenzt Verblasste Abyss-Artefakte zu farmen.",loc:"Welt-Drops, Belohnung aus Versiegelten Abyss-Artefakten; farmbar (VULKK). Käuflich laut questlog für 285 Kupfer bei den Hexen Areciel, Elowen, Bari und Lyselia; außerdem herstellbar bei Hexen (Blaupause: Verblasstes Abyss-Artefakt, 1 Abyss-Sphäre + 2 Quecksilber). Quelle: questlog.gg (Item 75002, Rezept 1000237), egamersworld, esports.gg, VULKK",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_deactived_abyss_artifact.webp"},
  {name:"Gold Bar",cat:"Währung & Progression",detail:"Höchste Wertstufe, nicht direkt ausgebbar. An jeder Bank gegen 500 Silber eintauschbar (und umgekehrt); der Verkauf an normale Händler bringt nur 190 Silber, daher immer zur Bank bringen. Genutzt für Bank-Investitionen (Deposit Box, passives Einkommen) und als schnellste Camp-Funds-Spende. Per Alchemie-Rezept craftbar: Rezept oben in der Spitze der Einsicht (Rätsel-Tower südlich von Hernand), hergestellt in einer Witch-Hideout aus Schwefel x3, Quecksilber x3, Silbererz x10 (questlog-Rezept 1000157; weitere Rezepte: 1 Goldener Apfel + 3 Golderz bei Hexen, 100 Golderz am Schmied). Herstellung/Rezept siehe Seiten Herstellen & Farmen und Hexen & Fusion. Weiterverarbeitung: 1 Goldbarren + 4 Schwefel + 3 Quecksilber + 2 Weihwasser ergeben bei einer Hexe 1 Platin (questlog-Rezept 1000072, Hexen-Werkbank; Areciel, Elowen, Bari, Lyselia, Sylvia) – Platin ist laut questlog-Item-Text nur von einer Hexe herstellbar („Can only be crafted by a witch“); daneben ist es Belohnung der Entsendung „Ruinenausgrabungen von Votudig“ (30 % Chance, questlog). questlog führt den Grundwert mit 50.000 Kupfer (= 500 Silber), das passt zum Bank-Kurs; der Händlerverkaufspreis von 190 Silber stammt aus den Guides und ist bei questlog nicht abgebildet.",loc:"Bank, Schatzkisten, Schatz-(Trader-)Goblins, Welt-Beute, Alchemie (Spire-of-Einsicht-Rezept); laut questlog außerdem bei sechs Händlern für je 50.000 Kupfer (Grover, Drakbar, Kabrok, Grovand, Braxil, Vrokan) bzw. bei Jasper für 10.000 Marni-Münze sowie Belohnung der Entsendung „Ruinenausgrabungen von Votudig“. Quelle: PowerPyx, KeenGamer, Game8, thegameswiki, questlog.gg (Item 53, Rezepte 1000072/1000157/1000158/1000159)",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_goldbar_0001.webp"},
  {name:"Hernand Refinement Token",cat:"Währung & Progression",detail:"Münze für Verfeinerung, der beim Gear-Upgrade die Herstellungsmaterialien ersetzt: pro Token steigt ein Ausrüstungsstück eine Stufe ohne Erze, Häute oder Ressourcen. Eingelöst bei Turnali, dem Blacksmith in Hernand-Stadt, im Refinement-Menü unter dem Reiter 'Refinement Tokens'. Wirkt laut Item-Text nur bei Ausrüstung, die weniger als fünfmal verfeinert wurde (questlog: 'refined less than five times'); die Guides nennen 'unter Stufe 4', die genaue Grenze ist daher um eine Stufe uneindeutig. Mit Erreichen der Grenze verschwindet die Token-Option. Mehrfach bestätigt (questlog, GamesGG, TheGamer, PC Gamer, Shacknews).",loc:"Belohnung aus Haupt- und Fraktionsquests in Hernand; Einlösung bei Turnali (Hernand-Stadt). Quelle: GamesGG, TheGamer, PC Gamer, Shacknews",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_itemupgrade_coin_hernand_00.webp"},
  {name:"Sealed Abyss Artifact",cat:"Währung & Progression",detail:"Verschlossener, polygonaler Würfel an Straßenschreinen/Altären in ganz Pywel. Bleibt im Inventar gesperrt, bis die daran gebundene versteckte Herausforderung abgeschlossen ist (z.B. Gegner mit bestimmter Waffe im Zeitlimit töten). Belohnung danach: ein reguläres Abyss-Artefakt, ein Verblasstes Abyss-Artefakt oder eine Abyss-Ausrüstung. Es gibt 141 davon in der Welt (egamersworld, esports.gg).",loc:"141 feste Fundorte an Straßen-Schreinen/Steinaltären in Pywel. Quelle: egamersworld, esports.gg, GameRant",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_abyss_artifact_c_0001.webp"},
  {name:"Silver",cat:"Währung & Progression",detail:"Standard-Handelswährung. Wird für fast alles ausgegeben: Vendoren, Schmiede/Refinement, Rüstung, Camp-Ausbau, Inventarerweiterung und Schließfächer. Umrechnung: 100 Kupfer = 1 Silber; 500 Silber = 1 Goldbarren an jeder Bank (4 Banken, gemeinsames Konto). Camp-Spende: Seit Patch 2.01.00 (04.09.2026) erhält man für gespendetes Silber die zehnfache Menge Camp-Mittel (offizielle Notes). Mehrfach bestätigt (Method.gg, PowerPyx, thegameswiki).",loc:"Gegner-Drops, Verkauf von Beute, Quests, Handel. Quelle: Method.gg, PowerPyx, thegameswiki",miss:false,conf:"high",icon:"cd_assets/items/silver.png"},
  {name:"Abyss Gear",cat:"Währung & Progression",detail:"Runen-/Orb-ähnliche Mods, die in Sockel von Waffen/Rüstung gesteckt werden und Statboni oder elementare Effekte (Feuer, Eis, Blitz) gewähren. Die Sockelung erfolgt an einer Witch-Hideout. Erhältlich als Belohnung aus Versiegelten Abyss-Artefakten, aus einzigartigem Welt-Equipment, von Bossen und aus Abyss-Schatzkisten; bei Hexen craftbar. Hinweis: Synthese/Cores laufen auf der eigenen Seite Abyss-Ausrüstung, hier nur als Progressions-Belohnungsitem erfasst.",loc:"Sealed-Artifact-Belohnung, Bosse, Abyss-Schatzkisten, Hexen-Herstellung/Sockelung. Quelle: GameRant, esports.gg, VULKK",miss:false,conf:"medium",icon:"cd_assets/items/abyss-gear.webp"},
  {name:"Delesyia Refinement Token",cat:"Währung & Progression",detail:"Regionale Variante der Münzen für Verfeinerung für das Delesyia-Gebiet. Gleiche Regeln wie Hernand- und Pailune-Token (materialfreies Gear-Upgrade für Ausrüstung, die weniger als fünfmal verfeinert wurde), nur in der zugehörigen Region einlösbar; laut Item-Text beim Schmied Renier. Wird erst im späteren Spielverlauf verfügbar.",loc:"Belohnung aus Haupt-/Fraktionsquests in Delesyia (questlog: u. a. 'Hand over the Delesyian wine', 'Hand over 2 chunks of tender meat'); Einlösung beim Schmied Renier. Quelle: questlog.gg (Item 1003831), TheGamer",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_itemupgrade_coin_delesyia_00.webp"},
  {name:"Demeniss Refinement Token",cat:"Währung & Progression",detail:"Regionale Münze für Verfeinerung, vom Regenten von Demeniss vergeben. Beim Schmied Jofrua eingelöst, deckt er die Materialkosten der Verfeinerung; laut Spieltext nur für Ausrüstung, die weniger als fünfmal verfeinert wurde (Grenze gegenüber der Guide-Angabe „unter Stufe 4“ ingame zu prüfen).",loc:"Belohnung u. a. der Händleraufträge „Kathors Anfrage“, „Khrons Anfrage“ und „Jofruas Anfrage“ (Geschichten des demenessischen Händlers) sowie der Mission „Der verfluchte Ritter“ (Nach Demeniss). Quelle: questlog.gg (item 1003830)",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_itemupgrade_coin_demeniss_00.webp"},
  {name:"Beighen Refinement Token",cat:"Währung & Progression",detail:"Regionale Münze für Verfeinerung, vom Oberhaupt von Beighen vergeben. Beim Schmied Forgehart eingelöst, deckt er die Materialkosten der Verfeinerung; laut Spieltext nur für Ausrüstung, die weniger als fünfmal verfeinert wurde.",loc:"Belohnung des Händlerauftrags „Richarts Anfrage“ (Geschichten der pailunischen Händler). Quelle: questlog.gg (item 1003833)",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_itemupgrade_coin_beighen_00.webp"},
  {name:"Tommaso Refinement Token",cat:"Währung & Progression",detail:"Regionale Münze für Verfeinerung, vom Bürgermeister von Tommaso vergeben. Beim Schmied Tibo eingelöst, deckt er die Materialkosten der Verfeinerung; laut Spieltext nur für Ausrüstung, die weniger als fünfmal verfeinert wurde.",loc:"Belohnung der Händleraufträge „Tibos Anfrage“ und „Brookners Anfrage“ (Geschichten der Händler der Roten Wüste). Quelle: questlog.gg (item 1003834)",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_itemupgrade_coin_tashkalp_00.webp"},
  {name:"Varnia Refinement Token",cat:"Währung & Progression",detail:"Regionale Münze für Verfeinerung, vom Bürgermeister von Varnia vergeben. Beim Schmied Samir eingelöst, deckt er die Materialkosten der Verfeinerung; laut Spieltext nur für Ausrüstung, die weniger als fünfmal verfeinert wurde.",loc:"Belohnung der Händleraufträge „Samirs Anfrage“ und „Omars Anfrage“ (Geschichten der Händler der Roten Wüste) sowie der Mission „Jagd jenseits des Schleiers“ (Verschleierte Hexe). Quelle: questlog.gg (item 1003851)",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_itemupgrade_coin_varnia_00.webp"},
  {name:"Pailune Refinement Token",cat:"Währung & Progression",detail:"Regionale Variante der Münzen für Verfeinerung für das Pailune-Gebiet. Funktioniert identisch zum Hernand-Token (ersetzt Refinement-Materialien, hebt Gear eine Stufe hoch, bis Stufe 4), kann aber nur bei einer Schmiede in der eigenen Region (Pailune) eingelöst werden. Laut Item-Text (questlog 1003832) gilt abweichend von der Guide-Angabe 'bis Stufe 4' die Grenze 'weniger als fünfmal verfeinert'; Herkunft laut questlog u. a. die Missionen 'Übergib den Dolch' und 'Hand over 3 short hair hides'; von TheGamer und PC Gamer bestätigt.",loc:"Belohnung aus Haupt-/Fraktionsquests in Pailune; Einlösung bei lokalem Schmiede in Pailune. Quelle: TheGamer, PC Gamer",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_itemupgrade_coin_pailune_00.webp"},
  {name:"Bounty Notice",cat:"Schlüssel- & Quest-Item",detail:"Steckbriefe/Kopfgeld-Aushänge, die einzelne Gesetzlose markieren und Kopfgeld-Nebenquests starten. Bekannte Varianten in Hernand (laut questlog 11): Jeffrey, Simon de Montfort, Alessio, Bianca, Blix, Salvatore, Warren, Ulzok, Haldin, Dante, Billy.",loc:"Von Laternenpfählen in der Stadt Hernand, am Bauernhof von Hernand und im Sumpfwurzel-Viehhof. Quelle: Game8 / Fextralife",miss:false,conf:"high",icon:"cd_assets/items/bounty-notice.webp"},
  {name:"Church Crypt Key",cat:"Schlüssel- & Quest-Item",detail:"Echtes Quest-/Schlüssel-Item. Wird während der Hauptquest 'Secret at the Church' (Mission 68, Kapitel 5) in Demeniss von der Äbtissin der Kirche von West-Demeniss übergeben und öffnet die Krypta im Hof hinter der Kirche (Abstieg über eine Leiter). In der Krypta führt ein Rätsel-Tresor (vier Ecken anschlagen, bis alle Symbole leuchten) zum Dolch der Ausstrahlung.",loc:"Demeniss, Hauptquest 'Secret at the Church', Kapitel 5. Quelle: crimsondesert.gaming.tools, Game8, Fextralife, VULKK, PowerPyx",miss:true,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0102_key_0001.webp"},
  {name:"Crane Control Room Key",cat:"Schlüssel- & Quest-Item",detail:"Beschreibung: 'A key that unlocks the crane control room's door. Access is restricted to authorized personnel only.' Erlaubt, den Kran zu bedienen und den Sealed-in-Stone-Questfortschritt im Steinbruch fortzusetzen.",loc:"Während der House-Roberts-Fraktionsquest 'Versiegelt im Stein' am Steinbruch Karin. Quelle: Fextralife / Game8",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0102_key_0001.webp"},
  {name:"Engraved Key",cat:"Schlüssel- & Quest-Item",detail:"Beschreibung: 'The wooden key glowed, transforming into an iron key. A mysterious symbol is engraved upon its surface.' Aus dem Schäbigen Holzschlüssel hervorgegangener Eisenschlüssel mit eingraviertem Symbol; dient dem Questfortschritt.",loc:"Erhalt durch Abschluss der Quest 'Heart Beyond Borders'. Quelle: Fextralife",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0102_key_0002.webp"},
  {name:"Gold Vein Map",cat:"Schlüssel- & Quest-Item",detail:"Schürf-/Goldader-Karte. Nach dem Verbrauch werden 10 Höhlen mit Golderz-Vorkommen auf der Weltkarte markiert (u.a. Ambosshügelhöhle in Demeniss, Goldmine am Wüstensee in Varnia, Höhle des Wächters in Delesyia).",loc:"Drop des Bosses Marnis Steinbruchmaschine im Steinbruch Karin (questlog-Mission 'Defeat Excavatron') (nördlich von Roccas Hügel, Hernand-Region). Quelle: GameRant / games.gg / Game8 / gaming.tools",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0050.webp"},
  {name:"Hidden Treasure Map Piece 7",cat:"Schlüssel- & Quest-Item",detail:"Teilstück einer versteckten Schatzkarte (Nr. 7) für eine Sammel-/Schatzquest. Eigenständig vom bereits erfassten Notorious Thief's Map Piece. Quelle: Game8 + Fextralife.",loc:"Drop (50 % Chance) bei Nebelforstjäger (8 Einträge plus Verkleideter Nebelforstjäger); außerdem mit sehr geringer Chance (0,1–0,2 %) Belohnung der Entsendungen „Ausgrabung der Zeitzerfressenen Ruinen“ und „Erkundung der Verheim-Ruinen“. Quelle: questlog.gg (Item 1002209), Fextralife.",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0137.webp"},
  {name:"Kuku Iron Pot",cat:"Schlüssel- & Quest-Item",detail:"Ein funktionales Schlüssel-Item und tragbares zwergisches Fertigungsgerät (questlog-Name: 'Kuku-Eisentopf', ID 53016; dort als Ausrüstung der Kuku-Bird-Gruppe geführt und zusätzlich über das Rezept 'Kuku-Eisentopf' herstellbar; questlog nennt außerdem die Mission 'Talk to the artisan' der Quest 'Invention of the Workshop' als Bezugsquelle). Der Topf nimmt Abyss-Objekte sowie Maschinenteile und Apparaturen auf (230 Plätze, jedoch keine normalen Items wie Nahrung, Waffen, Rüstungen oder Rezepte) und ist der Einstieg in ein tiefes Fertigungssystem für einzigartige Waffen, Rucksäcke, Elementar-Rüstung und Drachenreittier-Komponenten. Weitere Kuku-Items werden bei Grimnir gefertigt, zusätzliche Rezepte schalten sich ab Kapitel 5 (Hexen) und Kapitel 10 (Ironflame-Orcs) frei.",loc:"Erhalten in Kapitel 4 während der Hauptquest \"Geheimnisvoller Topf\" in der Kilnden-Werkstatt direkt westlich von Hernand: dort trifft man den Zwerg Grimnir, repariert die Brennöfen und fertigt den ersten Topf; die Bedienung lernt man beim Arbeiter Togrum. Quelle: GameSpot, Fextralife, Sportskeeda, VULKK",miss:false,conf:"high",icon:"cd_assets/items/kuku-iron-pot.webp"},
  {name:"Merchant Delivery Seal",cat:"Schlüssel- & Quest-Item",detail:"Ein offizielles Siegel der Blattgold-Händlergilde zur Beglaubigung von Handelslieferungen. Es kann nicht verkauft oder weggeworfen werden und dient während der Quest als eines der untersuchten Beweisstücke; sein Auftauchen außerhalb des Guildhouse belastet den Verdächtigen.",loc:"Liegt auf einem runden Tisch in Grimzles Haus in der Kohletalwerkstatt; wird während der Faktionsquest \"Glut gelöscht\" untersucht. Quelle: Fextralife, crimsondesert.app, thegameswiki",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_pendant_0001.webp"},
  {name:"Mysterious Elixir",cat:"Schlüssel- & Quest-Item",detail:"Ein Quest-Lieferobjekt: ein Trank aus unbekannten Zutaten, der nach Ziegenhörnern riecht; die Beschreibung legt nahe, dass die Banditen die gestohlenen Hörner als Zutat verwendeten. Kann nicht konsumiert, verkauft oder weggeworfen werden und dient ausschließlich der Questabgabe.",loc:"Wird während der Quest \"The Man Trapped in the Mire\" aus einer der Kisten neben dem weißen Stein am Banditenlager aufgenommen und anschließend dem erzürnten Rancher als Ausgleich für die gestohlenen Ziegenhörner übergeben. Quelle: Fextralife, PowerPyx, Sportskeeda, GameRant",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_potion_0002_r.webp"},
  {name:"Ruby Hilted Golden Dagger",cat:"Schlüssel- & Quest-Item",detail:"Ein goldener Dolch mit rubinbesetztem Griff (questlog-Name: 'Goldener Dolch mit rotem Edelstein', ID 1000514), ein Rätsel-Item der Quest 'Spuren im Anwesen' (Kapitel 3). Zusammen mit dem Sapphire Hilted Golden Dagger bildet er ein Paar: Werden beide Dolche in die zwei Halterungen über dem Kamin im Arbeitszimmer (Study) im Obergeschoss des Glenbright-Anwesens gesteckt, löst dies einen Mechanismus aus, das Bücherregal gleitet beiseite und gibt einen Geheimgang in den Keller frei (mit Wolkenwagen-Blaupause, Meliaras Elixier-Rezept u.a.).",loc:"Liegt auf einer Wandhalterung im Obergeschoss des Glenbright-Anwesens; Quest 'Spuren im Anwesen', Kapitel 3. Quelle: GameRant, Game8, VGC",miss:false,conf:"high",icon:"cd_assets/items/ruby-hilted-golden-dagger.webp"},
  {name:"Sapphire Hilted Golden Dagger",cat:"Schlüssel- & Quest-Item",detail:"Ein goldener Dolch mit saphirbesetztem Griff (questlog-Name: 'Goldener Dolch mit blauem Edelstein', ID 1000581), das Gegenstück zum Ruby Hilted Golden Dagger ('Goldener Dolch mit rotem Edelstein') in der Quest 'Spuren im Anwesen' (Kapitel 3). Beide Dolche müssen in die Halterungen über dem Kamin im Arbeitszimmer des Glenbright-Anwesens gesetzt werden, um den geheimen Durchgang hinter dem Bücherregal in den Keller zu öffnen.",loc:"Hinter einem Umgebungsrätsel im Glenbright-Anwesen versteckt: Links neben einer Statue befindet sich ein mit einem Zahnrad verbundener Schrank; man dreht das darin liegende Handrad, bis das Licht des Kronleuchters auf die Statue fällt, woraufhin sich eine Wandnische öffnet und den Dolch freigibt. Quest 'Spuren im Anwesen', Kapitel 3. Quelle: GameRant, Game8",miss:false,conf:"high",icon:"cd_assets/items/sapphire-hilted-golden-dagger.webp"},
  {name:"Scales of Fairness and Justice",cat:"Schlüssel- & Quest-Item",detail:"Beschreibung: 'An honorable emblem awarded to a knight who fought for fairness and justice.' Wer das Emblem trägt, genießt tiefes Vertrauen der Händler und erhält stets günstige Handelskonditionen.",loc:"Quest-Belohnung (Keepsake). Quelle: Fextralife / gaming.tools / questlog.gg",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_demian_item_scale.webp"},
  {name:"Shabby Wooden Key",cat:"Schlüssel- & Quest-Item",detail:"Beschreibung: 'A gift from a beggar near the Hernand Tavern. Timeworn and dirty, it appears to open nothing.' Wandelt sich später in den Gravierten Schlüssel. Hinweis: Game8 führt dasselbe Item als 'Old Shabby Key'.",loc:"Vom Bettler nahe der Hernand-Taverne während der 'Mysterious Man'-Quest. Quelle: Fextralife / Game8",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0102_key_0003.webp"},
  {name:"Shai's Pendant",cat:"Schlüssel- & Quest-Item",detail:"Ein leuchtendes Schlüssel-/Story-Item, das eine geheimnisvolle Verbindung zum Abyss besitzt und den Protagonisten mit dem Volk der Shai und den Geheimnissen des Dorfes Pororin verbindet. Es wird von Rulupee zurückgelassen.",loc:"Belohnung der Quest 'Heart Beyond Borders': Man läuft zum Haus westlich des Hernand-Inn, spricht mit Rulupee (Kind mit grüner Kapuze) und fängt deren Katze Jiji auf dem Dach ein. Nach Abschluss verschwindet Rulupee um die Ecke und das Pendant liegt auf dem Boden, wo man es aufsammelt. Quelle: Fextralife, GameSpot, Gamer Guides",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_clue_pendant_0001.webp"},
  {name:"St. Halssius Visitor Pass",cat:"Schlüssel- & Quest-Item",detail:"Ein Besuchspass, der während der Quest 'Familiar Curses' Zutritt zu St. Halssius' House of Healing gewährt. Trotz Beschreibung als Pass mit begrenzter Nutzung erlaubt er Kliff tatsächlich beliebigen wiederholten Eintritt: Man legt ihn am Haupttor an der Westseite des Geländes vor, woraufhin die Wachen den Pass prüfen und durchlassen.",loc:"Vom Priester (Alfred) in der Kirche von Hernand in der Stadt Hernand für 10 Silber erhältlich. Alternativen: eine Halssius-Verkleidung von einem NPC an der Außenmauer (ebenfalls ca. 10 Silber) oder das Hineinschleichen ohne Kauf. Quelle: GameSpot, GameRant, Fextralife",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0035.webp"},
  {name:"Stellen Manor Closet Key",cat:"Schlüssel- & Quest-Item",detail:"Schlüssel, den man aus dem Melodie-Tresor (Tastenreihenfolge 1,3,4,2,1,3,4) im Stellen-Anwesen stiehlt. Öffnet den Kleiderschrank/Wandschrank im Schlafzimmer der oberen Etage; dahinter beginnt der Pfad (Handrad, Buch, Bücherregal hinter dem Widder-Gemälde) zur Folterkammer im Keller, in der das Acria-Schwert liegt.",loc:"Aus der Melodie-Tresor im Stellen-Anwesen (nordöstlich von Hernand, oberes Stockwerk). Quelle: TheGamer / GameRant / games.gg",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_key_0005.webp"},
  {name:"White Crow's Letter",cat:"Schlüssel- & Quest-Item",detail:"Beschreibung: 'A letter from Weiße Krähe about Abyss Nexuses.' Quest-Brief der Weißen Krähe; kann nicht verkauft werden, dient dem Story-Fortschritt (Abyss-Nexus-Strang).",loc:"Vom Weiße Krähe übergeben (nach Einsetzen aller vier Witch's Tokens). Quelle: Game8 / Fextralife",miss:false,conf:"high",icon:"cd_assets/items/white-crow-s-letter.webp"},
  {name:"Witch's Token",cat:"Schlüssel- & Quest-Item",detail:"Quest-Item, das man von jeder der vier regionalen Hexen erhält, nachdem deren Sanktum-Queststrang abgeschlossen und die Hexe erneut besucht wurde. Alle vier in das Loch der Tür eingesetzten Token öffnen das Versteck der sechsten Hexe, der Weißen Krähe, im Irrwald.",loc:"Je ein Token von Elowen, Bari, Lyselia und Areciel nach deren Sanktum-Quest. Quelle: VULKK / Game8 / GameRant",miss:false,conf:"high",icon:"cd_assets/items/witch-s-token.webp"},
  {name:"Devil of the Reed Field's Doll",cat:"Schlüssel- & Quest-Item",detail:"Quest-Item (Puppe), das auf einem Altar aufgenommen wird (Missability nicht unabhängig bestätigt).",loc:"Auf einem Altar während der Quest 'Das Gesicht hinter der Maske'. Quelle: Game8",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_reeddevil_doll.webp"},
  {name:"Glenbright Manor Key",cat:"Schlüssel- & Quest-Item",detail:"Eisentür-Schlüssel aus Count Graces Glenbright Manor (questlog: 'A key found in Count Grace's Glenbright Manor. It looks like it unlocks a door leading to one of the manor's restricted, hidden areas.'); Guides führen ihn als 'Grace Manor Iron Door Key' (liegt auf dem Schreibtisch neben dem Diener). Daneben gibt es den 'Kellerschlüssel des Glenbrigh-Anwesens' (Guides: 'Grace Manor Basement Key'; in einem Geheimraum hinter einem Gemälde zweier zu Pferd kämpfender Ritter nahe der Treppe; öffnet eine separate verschlossene Tür, nachdem man bereits im Keller ist). Der Keller selbst wird nicht mit diesem Schlüssel betreten, sondern über einen Geheimgang/das Kamin-Dolch-Rätsel erschlossen. Beide Schlüssel stammen aus der Hauptquest 'Spuren im Anwesen' (Kapitel 3).",loc:"Glenbright/Grace Manor, Hauptquest 'Spuren im Anwesen', Kapitel 3. Quelle: Game8, The Games Wiki, TheGamer, VGC, Fextralife",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0102_key_0001.webp"},
  {name:"Grace Manor Basement Key",cat:"Schlüssel- & Quest-Item",detail:"Öffnet eine verschlossene Tür im Keller des Glenbright/Grace Manor (Anwesen von Count Grace). questlog führt das Item als 'Kellerschlüssel des Glenbrigh-Anwesens' (ID 802927) und vermerkt: 'Its use is not so clear yet.'",loc:"Im Inneren des Glenbright-Anwesens gefunden (Hauptquest 'Spuren im Anwesen', Kapitel 3). Quelle: Game8, questlog.gg",miss:false,conf:"medium",icon:"cd_assets/items/grace-manor-basement-key.webp"},
  {name:"Grace Manor Iron Door Key",cat:"Schlüssel- & Quest-Item",detail:"Öffnet die Eisentür im Grace/Glenbright-Anwesen. Identisch mit dem Eintrag 'Schlüssel zur eisernen Tür des Glenbright-Anwesens' (questlog-Name, ID 802926, DE 'Schlüssel zur eisernen Tür des Glenbright-Anwesens').",loc:"Im Inneren des Glenbright-Anwesens gefunden (Hauptquest 'Spuren im Anwesen', Kapitel 3). Quelle: Game8, questlog.gg",miss:false,conf:"medium",icon:"cd_assets/items/grace-manor-iron-door-key.webp"},
  {name:"Hidden Treasure Map Piece 8",cat:"Schlüssel- & Quest-Item",detail:"Teilstück einer versteckten Schatzkarte (Nr. 8). Quelle: Fextralife (Key Items).",loc:"Drop (20 % Chance) bei Wolfspirscher und Hauptmann des Angriffstrupps der Wolfspirscher; außerdem in Schatztruhen (sieben Schatztruhen, Gift of Reminiscence) sowie mit sehr geringer Chance (0,1–0,2 %) Belohnung der Entsendungen „Ausgrabung der Zeitzerfressenen Ruinen“ und „Erkundung der Verheim-Ruinen“. Quelle: questlog.gg (Item 1002210), Fextralife.",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0138.webp"},
  {name:"Key to the Spire of the Stars",cat:"Schlüssel- & Quest-Item",detail:"Beschreibung: 'A key given by Grundir. The key is required to enter the Spire of the Stars, which is on the hill behind the Scholastone Institute.' questlog-Name: 'Spire of the Stars Key' (ID 1001197).",loc:"Von Grundir gegeben; laut questlog Belohnung der Missionen 'Observe Octavius's Abyss experiment' und 'Stelle den Abyss wieder her'. Quelle: questlog.gg, Fextralife",miss:false,conf:"high",icon:"cd_assets/items/key-to-the-spire-of-the-stars.webp"},
  {name:"Memories of Abundance",cat:"Schlüssel- & Quest-Item",detail:"Kristall aus geschichteten Erinnerungen, durchdrungen vom Wissen über verborgene Orte in Hernand; Questfortschritt/Sammelstück.",loc:"Belohnung für das Abschließen der Dragon's-Stone-Chamber-Ruinen-Challenge. Quelle: Fextralife / questlog.gg",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_cd_boss_reward_treasuremap.webp"},
  {name:"Notorious Thief's Map Piece",cat:"Schlüssel- & Quest-Item",detail:"Teilstück einer Schatzkarte des berüchtigten Diebes (questlog führt drei Stücke: 'Notorious Thief's Map Piece 1' bis '3', IDs 803011-803013; Beschreibung: 'A map marking a specific location. The surrounding landmarks should help identify it.'); führt zu einer Schatzbelohnung (u.a. Aschenflammen-Plattenumhang).",loc:"Im Hernandian-Gebiet / Wolfswald gefunden (Piece 1). Quelle: questlog.gg / gaming.tools / Gamer Guides",miss:false,conf:"medium",icon:"cd_assets/items/notorious-thief-s-map-piece.webp"},
  {name:"Ordinary Door Key",cat:"Schlüssel- & Quest-Item",detail:"Ein einfacher, verbrauchbarer Schlüssel, der die meisten gewöhnlichen Türen öffnet und so Zugang zu verschlossenen Räumen und versteckten Bereichen verschafft. Es ist der generische Tür-Schlüssel des Spiels (questlog führt ihn schlicht als 'Key', ID 30041: 'A key. It should open most ordinary doors.'; bei vielen Händlern kaufbar, u. a. Aegrin, Slywek, Smaya, Skeent, Ladolph), der beim Durchschreiten einer verschlossenen Tür automatisch aufgebraucht wird. Er ist nicht an eine bestimmte Tür gebunden, funktioniert aber nicht bei eigens benannten Quest-Türen.",loc:"Wird u.a. beim Erkunden von Burg Schmorstein im Süden von Demeniss gefunden; zusätzlich als Beute von Gegnern (geringe Drop-Chance) sowie im Back-Alley-Shop gegen Münzen erhältlich. Quelle: Game8, GAMES.GG, questlog.gg",miss:false,conf:"medium",icon:"cd_assets/items/ordinary-door-key.webp"},
  {name:"Prison Key",cat:"Schlüssel- & Quest-Item",detail:"Beschreibung: 'Standard key used for cells holding criminals.' Öffnet Gefängniszellen.",loc:"In der Welt gefunden. Quelle: Fextralife",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0102_key_0001.webp"},
  {name:"Seal of Greed - Goldleaf Merchant Guild",cat:"Schlüssel- & Quest-Item",detail:"Quest-Item/Handelsberechtigung der Blattgold-Händlergilde; dient dem Questfortschritt.",loc:"Von einem Goldleaf-Händler nach Abschluss von Kapitel 2. Quelle: Game8",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_cd_boss_reward_merchantking.webp"},
  {name:"Spire of Clockwork Key",cat:"Schlüssel- & Quest-Item",detail:"Öffnet das Vordertor der Uhrwerkspitze.",loc:"Drop von Lucian Bastier nach Abschluss von Kapitel 8; am Vordertor der Spire verwendet. Quelle: GameRant / Game8",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_marni_emp_capsule_0001_parts02.webp"},
  {name:"Sungrove Manor Key",cat:"Schlüssel- & Quest-Item",detail:"Belohnung aus dem geheimen Tresor des Sonnenhain-Anwesens (Puzzle: einzelne Quadrate drehen, bis das Bild vollständig ist); schaltet weitere Inhalte im Manor frei.",loc:"Tresor im Sonnenhain-Anwesen (bei M in Demeniss, oberes Stockwerk am Ende des Korridors). Quelle: questlog.gg / gaming.tools / Gamer Guides / games.gg",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_key_0004.webp"},
  {name:"Thornbriar Dungeon Key",cat:"Schlüssel- & Quest-Item",detail:"Schlüssel zu den Zellen des Thornbriar-Dungeons, von dessen Existenz nur wenige wissen.",loc:"Als Tisch-Item im Gefängnis der eisernen Maske gefunden. Quelle: questlog.gg / gaming.tools",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_key_0006.webp"},
  {name:"Master Key",cat:"Schlüssel- & Quest-Item",detail:"Schlüssel, der laut Item-Text („A key that can open any door“) jede Tür öffnet. Die Hexen der Demut-Questreihe (Lyselia) geben ihn als Belohnung der Sanktum-Missionen Devotion, Veneration, Oblation und Faith (je ein Generalschlüssel); questlog führt außerdem die Mission „Help the person hanging on the bridge“ als Quelle.",loc:"Missionsbelohnung „Talk to the witch at the Sanctum of Devotion / Veneration / Oblation / Faith“ (Quest Hexe der Demut) sowie der Mission „Help the person hanging on the bridge“ (questlog). Quelle: questlog.gg (Item 1002294)",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0102_key_0001.webp"},
  {name:"Dagger of Radiance",cat:"Schlüssel- & Quest-Item",detail:"Alter Dolch aus dem Kellergewölbe der Kirche; er wird gebraucht, um das Tor zum Krähennest zu öffnen (questlog). Liegt in der Krypta hinter dem Rätsel-Tresor (siehe Schlüssel zum Vorratslager im Kirchenkeller).",loc:"Krypta der Kirche von West-Demeniss (Hauptquest „Secret at the Church“). Quelle: questlog.gg (Item 1000151), Game8",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_sword_gold_0002.webp"},
  {name:"Gate of Peace Disruptor Key",cat:"Schlüssel- & Quest-Item",detail:"Schlüssel, der den Disruptor am Tor des Friedens in Gorthak aktiviert (Item-Text).",loc:"Belohnung der Mission „Go to the Gate of Peace“. Quelle: questlog.gg (Item 1000497)",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_marni_emp_capsule_0001_parts01.webp"},
  {name:"Hernand Castle Basement Key",cat:"Schlüssel- & Quest-Item",detail:"Schlüssel zum verschlossenen Keller von Burg Hernand, in dem der Weinvorrat der Burg lagert. Daneben führt questlog den „Hernand Weinkeller-Schlüssel“ (Item 802353) – laut Item-Text haben viele Diebe versucht, ihn zu stehlen; ob beide Schlüssel dieselbe Tür betreffen, ist nicht belegt.",loc:"Belohnung der Mission „Finde den helfenden Heiler“. Quelle: questlog.gg (Items 1000707, 802353)",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0102_key_0001.webp"},
  {name:"Witch's Storehouse Key",cat:"Schlüssel- & Quest-Item",detail:"Schlüssel zum geheimen Vorratslager der Hexe Weiße Krähe; sie hat dort ein „besonderes Geschenk“ vorbereitet und gibt den Schlüssel selbst (Item-Text).",loc:"Von Weiße Krähe ausgehändigt. Quelle: questlog.gg (Item 1001176)",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_key_0003.webp"},
  {name:"Beacon Key",cat:"Schlüssel- & Quest-Item",detail:"Öffnet das Tor einer Beacon-Anlage („when security is tight, this key is required“); bei gewöhnlichen Türen nicht nötig.",loc:"Drop beim Ritter des Leuchtfeuers. Quelle: questlog.gg (Item 30051)",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0102_key_0001.webp"},
  {name:"Iron Gate Key",cat:"Schlüssel- & Quest-Item",detail:"Robuster Schlüssel, der laut Item-Text auch Eisentüren öffnet.",loc:"Drop bei Manor Guards. Quelle: questlog.gg (Item 30059)",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0102_key_0001.webp"},
  {name:"Fort Anvil Key",cat:"Schlüssel- & Quest-Item",detail:"Schlüssel zu Festung Amboss (Item-Text ohne weitere Angaben).",loc:"Drop bei Wandernde Freiklinge. Quelle: questlog.gg (Item 1002985)",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_key_0006.webp"},
  {name:"Hidden Treasure Map Piece 1–6 und 9–12",cat:"Schlüssel- & Quest-Item",detail:"Die zwölf nummerierten Stücke der „Hidden Treasure Map“ (Item-Text: „A map showing the area around a marked location. Identifying the region will reveal the spot.“). Stück 7 und 8 stehen als eigene Einträge; hier die übrigen: Stück 1 (Item 1002144), 2 (1002171), 3 (1002205), 4 (1002206), 5 (1002207), 6 (1002208), 9 (1002211), 10 (1002212), 11 (1002213), 12 (1002395).",loc:"Stück 1: Missionsbelohnung „Besiege Hornspalter“. Stück 2 und 12: Drop bei Beggars. Stück 3, 4, 5 und 9: Missionsbelohnung „Die Situation vor und nach Pailune untersuchen“. Stück 6: Schatztruhen. Stück 10 und 11: nur als Entsendungsbelohnung. Alle Stücke außer Nr. 12 sind zusätzlich mit sehr geringer Chance (0,1–0,2 %) Belohnung der Entsendungen „Ausgrabung der Zeitzerfressenen Ruinen“ und „Erkundung der Verheim-Ruinen“. Der Zielort der Karte ist bei questlog nicht erfasst. Quelle: questlog.gg",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0131.webp"},
  {name:"Dead Pirate King's Treasure Map",cat:"Schlüssel- & Quest-Item",detail:"Karte, die dem vermeintlichen Piratenkönig gehört haben soll und auf einen bestimmten Ort zeigt (Item-Text).",loc:"Bezugsquelle bei questlog nicht erfasst. Quelle: questlog.gg (Item 1002079)",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0050.webp"},
  {name:"Alden's Poster",cat:"Quest-Dokument & Notiz",detail:"Ein Aushang/Poster von Alden, dessen Aufnahme die Nebenquest \"Anfrage von Alden\" (Aufträge in Hernand) auslöst. Alden betreibt den Hernand Gemischtwarenladen und bittet um Hilfe, mehr Kunden für seinen Laden zu gewinnen. Verfügbar ab Kapitel 3.",loc:"Findet sich am Anschlagbrett (Anschlagtafel) des Blattgold-Gildenhauses. Quelle: Fextralife, Game8.",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0184.webp"},
  {name:"Alustin's Letter",cat:"Quest-Dokument & Notiz",detail:"Ein versiegelter Brief von Alustin, der sich für die unhöfliche Art der Zustellung entschuldigt und den Spieler bittet, die dunklen Ausstrahlungen am Scholastein-Institut zu untersuchen. Der Brief muss im Inventar gelesen werden, um den Questfortschritt auszulösen.",loc:"Wird in der Stadt Hernand übergeben: Beim Vorrücken zur orangefarbenen Markierung rempelt ein unbenannter NPC den Spieler an und hinterlässt den Brief; Teil der Hauptquest \"Alustins Worte\". Erscheint der NPC nicht, hilft Speichern und Neuladen. Quelle: Fextralife, PowerPyx, nerdschalk, Game8",miss:false,conf:"high",icon:"cd_assets/items/alustin-s-letter.webp"},
  {name:"Annabella's Poster",cat:"Quest-Dokument & Notiz",detail:"Ein Aushang von Annabella, dessen Aufnahme die Nebenquest \"Anfrage von Annabella\" auslöst. Annabella betreibt die Hernand Sattler und bittet darum, einen großschuppigen Fisch (Schleie) zu fangen, dessen Schuppen sie für modischere Sättel verwenden will.",loc:"Am Anschlagbrett (Anschlagtafel) auf dem Platz der Stadt Hernand; verfügbar nach Abschluss der Quest \"Wo Gerüchte entstehen\". Alternativ kann Annabella direkt an der Hernand Sattler angesprochen werden. Quelle: Fextralife, Game8.",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0198.webp"},
  {name:"Bounty Notice - Alessio",cat:"Quest-Dokument & Notiz",detail:"Ein Kopfgeldaushang für den Gesetzlosen Alessio, der wegen des Betriebs einer illegalen Organisation und wegen Mordes gesucht wird. Das Item kann nicht verkauft werden und startet das Festsetzen Alessios; bei der Wache abgegeben bringt es 20 Silber bei lebender Abgabe (bei Tötung die Hälfte; MapMaster) und Hernand-Beitrags-EXP.",loc:"Wird von einem Laternenpfahl in der Stadt Hernand eingesammelt; Alessio selbst lauert laut Guides südöstlich von Hernand im Grünfeldhochland nahe dem Eisenholz-Banditenlager (MapMaster nennt abweichend: nordöstlich des Sanktums der Reue; questlog-Missionstext: Mord nahe dem Südlichen Steinbruch). Quelle: Fextralife, thegameswiki, sportskeeda, crimsondesert.gaming.tools, MapMaster (Steckbrief), questlog.gg (Mission 1000347)",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0108.webp"},
  {name:"Bounty Notice - Bianca",cat:"Quest-Dokument & Notiz",detail:"Ein Kopfgeldaushang für Bianca, eine Auftragsmörderin, die nahe dem Hügelanwesen gesichtet wurde. Das Lesen schaltet die Kopfgeld-Fraktionsquest \"Kopfgeldausschreibung - Bianca\" (Haus Celeste) frei; Bianca streift um die Kirche von Hernand (Suche auf dem Friedhof beginnen), die Belohnung beträgt 5 Silber (bei Tötung die Hälfte; MapMaster) plus 300 Hernand-Beitrag (Einzelquelle, bei MapMaster nicht beziffert; MapMaster schreibt nur „Beitrag EXP wird unabhängig von lebend/tot vergeben“). Das Poster erhält man zusätzlich als Belohnung der Mission „Lies den Brief“ (Quest „Der Sprung des Riesen“; questlog).",loc:"Poster erscheint zufällig in der Stadt Hernand (Kapitel 2, Bounty-System aktiv); Bianca selbst bei der Kirche von Hernand. Quelle: questlog.gg, MapMaster, thegameswiki",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0081.webp"},
  {name:"Bounty Notice - Blix",cat:"Quest-Dokument & Notiz",detail:"Ein Kopfgeldaushang für den Gesetzlosen Blix (grüner Goblin), der wegen unerlaubten Plünderns von Ruinen gesucht wird. Das Lesen schaltet die Kopfgeld-Fraktionsquest \"Kopfgeldausschreibung - Blix\" (Haus Celeste) frei; Blix hält sich nur tagsüber (ca. 6-13 Uhr) in einer kleinen Schlucht am Fuß der Bergwand bei Einhornklippe auf. Lebend abgeliefert gibt es die volle Belohnung (15 Silber), bei Tötung die Hälfte (7,5 Silber; PowerPyx und MapMaster stimmen überein, das Zeitfenster 6–13 Uhr nennt PowerPyx: „between 6AM to 1PM“).",loc:"Poster erscheint zufällig in der Stadt Hernand (Kapitel 2, Bounty-System aktiv); Blix selbst südöstlich von Hernand bei Einhornklippe, westlich des Blattgold-Gildenhauses. Quelle: questlog.gg, PowerPyx, GamerGuides, MapMaster",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0107.webp"},
  {name:"Bounty Notice - Jeffrey",cat:"Quest-Dokument & Notiz",detail:"Ein Kopfgeld-Aushang für Jeffrey, der in der Stadt Hernand Geld von Bürgern stiehlt (Taschendiebstahl). Das Lesen bzw. Annehmen schaltet die einführende Kopfgeldquest \"Steckbrief: Jeffrey\" frei, die zugleich das Bounty-System erklärt und als Belohnung eine Maske gibt.",loc:"Wird zu Beginn von Kapitel 2 von Pedro, dem Hernand-Wachhauptmann, an der Wache außerhalb der Stadt Hernand erhalten (links vom Plaza-Ausgang). Quelle: Fextralife, Game8.",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0077.webp"},
  {name:"Bounty Notice - Salvatore",cat:"Quest-Dokument & Notiz",detail:"Ein Kopfgeld-Aushang für den gesuchten Gesetzlosen Salvatore. Das Lesen des Dokuments schaltet die Fraktions-/Kopfgeldquest \"Steckbrief: Salvatore\" frei; Salvatore selbst hält sich im Sonnenuntergangstal südlich von Hernand auf und ist eine der neun Gesetzlosen-Bounties der Region.",loc:"Als violettes Poster-Symbol an Anschlagbrettern und Holzpfählen in der Stadt Hernand zu finden. Quelle: Fextralife, Game8, GameRant.",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0082.webp"},
  {name:"Bounty Notice - Simon de Montfort",cat:"Quest-Dokument & Notiz",detail:"Ein Kopfgeld-Aushang für Simon de Montfort, der wegen Honigdiebstahls aus der Imkerei Pollenhof gesucht wird. Das Lesen schaltet die Fraktionsquest \"Steckbrief: Simon de Montfort\" frei; Simon wird zuletzt nahe der Nektarwald-Imkerei gesehen und soll lebend ausgeliefert werden (bei Tötung nur halbe Belohnung).",loc:"Als violettes Poster-Symbol an Anschlagbrettern und Holzpfählen im Dorf Hernand erhältlich; Simon hält sich im Winterbergbecken südwestlich des Scholastein-Instituts auf. Quelle: Fextralife, Game8, GameRant, questlog.gg.",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0078.webp"},
  {name:"Bounty Notice - Warren",cat:"Quest-Dokument & Notiz",detail:"Ein Kopfgeld-Aushang für den Gesetzlosen Warren. Das Lesen des Dokuments schaltet die Fraktionsquest \"Steckbrief: Warren\" frei; Warren hält sich später im Gebiet des Pororin-Walds auf.",loc:"Wird an einem Laternenpfahl auf dem Sumpfwurzel-Viehhof südöstlich der Stadt Hernand gefunden. Quelle: Fextralife, Game8, questlog.gg.",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0084.webp"},
  {name:"Bran's Poster",cat:"Quest-Dokument & Notiz",detail:"Ein Aushang am Schwarzen Brett, auf dem Bran ein gebrauchtes, gut erhaltenes Spinnrad zum Verkauf anbietet, das er nicht an jeden abgeben will. Das Lesen des Posters schaltet die Fraktionsquest „Anfrage von Bran“ (Aufträge in Hernand) frei.",loc:"An der Anschlagtafel (Schwarzes Brett) in der Stadt Hernand zu Beginn von Kapitel 3 aufzunehmen; Bran selbst findet man in seinem Laden östlich des Schere-Stein-Papier-Minispiels. Quelle: Game8, Sportskeeda",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0161.webp"},
  {name:"Bruna's Note",cat:"Quest-Dokument & Notiz",detail:"Eine Notiz, die der Spielcharakter Kliff im Verlauf von \"Anfrage von Bruna\" von Bruna überreicht bekommt; sie besagt, dass der belieferte Kunde (Sattler) am Hernand Stable arbeitet, und schickt Kliff dorthin, um Rückmeldung zum neuen Sattelzeug einzuholen.",loc:"Wird während der Quest \"Anfrage von Bruna\" von Bruna in der Equinisher Saddlery überreicht und führt anschließend zum Stable in bzw. nördlich der Stadt Hernand. Quelle: Fextralife, GAMES.GG",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0148.webp"},
  {name:"Bruna's Poster",cat:"Quest-Dokument & Notiz",detail:"Ein nicht verkäuflicher Aushang mit dem Text, dass Bruna, die Sattlerin der Equinisher Saddlery, Hilfe braucht; das Lesen schaltet die Faktionsquest \"Anfrage von Bruna\" frei.",loc:"Wird von der Anschlagtafel (Schwarzes Brett) in der Stadt Hernand abgenommen. Quelle: Fextralife, Game8",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0185.webp"},
  {name:"Empty Ledger",cat:"Quest-Dokument & Notiz",detail:"Ein leeres Kassenbuch, das als Beweisstück in der Goldleaf-Faktionsuntersuchung dient. Es ist eines von drei Beweisstücken, die man am Arbeitsplatz von Grimzle prüft (neben Liefersiegel des Händlers und Übernachtungsnachweis), um ihn als Verräter zu überführen.",loc:"Liegt auf dem Studiertisch in Grimzles Haus in der Kohletalwerkstatt; untersucht in der Teilquest \"Grimzle, the Ledger Manager\" innerhalb von \"Glut gelöscht\". Quelle: Fextralife, camzillasmom, GamerGuides",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_gimmick_item_book_06.webp"},
  {name:"Fee Notice",cat:"Quest-Dokument & Notiz",detail:"Eine Gebührenmitteilung (questlog-Name: 'Steuerbescheid', ID 1003254: 'A notice listing the taxes Nogle must pay.'), die laut Fextralife dokumentiert, dass Nogle 12 Silber für Gildenbeiträge und Lagernutzungsgebühren zahlte; eines der Beweisstücke, die man bei der Untersuchung von Nogle prüft.",loc:"Im Blattgold-Gildenhaus, wo Nogle einen Laden prüft, auf einer Kiste unter dem Weinregal des Ladens; Teil der Teilquest \"Nogle, the Handelsverwalter\" in \"Glut gelöscht\". Quelle: Fextralife, camzillasmom",miss:false,conf:"high",icon:"cd_assets/items/fee-notice.webp"},
  {name:"Feed Purchase Receipt",cat:"Quest-Dokument & Notiz",detail:"Eine Futter-Kaufquittung (5 Säcke Heufutter zu je 5 Kupfermünzen, gesamt 25 Kupfer, von Blique, Pferdemanager), die zusammen mit den Mieteinträgen des Pferdestalls als Beweis in der Untersuchung geprüft wird.",loc:"Auf einer Kiste neben der Eingangstür in Bliques Haus im Blütenwaldhof; untersucht in der Teilquest \"Blique, the Horse Manager\" innerhalb von \"Glut gelöscht\". Quelle: Fextralife, camzillasmom, YouTube-Walkthrough",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_goblin_merchant_warranty.webp"},
  {name:"Guard's Letter",cat:"Quest-Dokument & Notiz",detail:"Ein Lese-Brief voller Sehnsucht nach der Familie; ein Wächter schreibt, dass er seine Angehörigen vermisst. Eines der Beweisstücke, die während der Fraktionsquest \"Glut gelöscht\" untersucht werden.",loc:"Liegt auf einer Kiste neben dem Vorratssack beim Amboss in Kathans Lager außerhalb des Goldleaf-Gildenhauses. Quelle: Fextralife, Gamer Guides",miss:true,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0225.webp"},
  {name:"Guard's Report",cat:"Quest-Dokument & Notiz",detail:"Ein Lese-Bericht, der festhält, dass beim Patrouillieren von Grimzles Residenz keine unbefugten Zutritte oder verdächtigen Aktivitäten festgestellt wurden. Wird Shakatu als letztes Beweisstück aus Kathans Aussage übergeben; er schließt daraus, dass nur Nogle und Grimzle die Handelsroute kennen. Teil der Fraktionsquest \"Glut gelöscht\".",loc:"Liegt auf einer Kiste neben den Fässern in Kathans Lager, wo sich drei Goblins miteinander rangeln, nahe einem weißen Zelt. Quelle: method.gg, camzillasmom",miss:true,conf:"high",icon:"/assets/_sprites/itemicon_goblin_merchant_warranty.webp"},
  {name:"Horn Thief",cat:"Quest-Dokument & Notiz",detail:"Ein Steckbrief bzw. Aushang am Schwarzen Brett, der jemanden sucht, der den Dieb fasst, welcher den Ziegen die Hörner abgeschnitten und gestohlen hat. Das Lesen dieses Posters startet die zur Questreihe \"Hernand im Chaos\" gehörende Hauptquest \"The Man Trapped in the Mire\" und führt in das Lesen von Erinnerungen ein.",loc:"Wird durch das Lesen des Steckbriefs \"Hörnerdieb\" am Anschlagbrett im frühen Spielverlauf (Kapitel 2, Umfeld Hernand) ausgelöst; vor Ort liest man die Hornlose-Ziege-Erinnerung mittels Laterne und der zuvor erhaltenen Visione. Quelle: Game8, Fextralife, GameRant, crimsondb.gg",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_quest_800180.webp"},
  {name:"Horse Hire Ledger",cat:"Quest-Dokument & Notiz",detail:"Ein Pferdevermietungs-Register (letzter Mieter Zelmigr, 3 Silber Pfand für 3 Brown Herspia Stallion). Es wird Shakatu als Beweis übergeben, weil Blique erkennt, dass der Verräter unter den maskierten Männern ist, die Pferde mieteten.",loc:"Auf dem Tisch am Eingang von Bliques Haus im Blütenwaldhof (östlich des Handelspostens der Blattgold-Händlergilde); untersucht in der Teilquest \"Blique, the Horse Manager\" innerhalb von \"Glut gelöscht\". Quelle: Fextralife, camzillasmom, crimsondesert.app",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_gimmick_item_book_06.webp"},
  {name:"Investigative Log: Extinguish the Flames",cat:"Quest-Dokument & Notiz",detail:"Ein Ermittlungsprotokoll (questlog-Name: 'Investigative Log: Glut gelöscht', ID 1000061), das die Namen der unter Verdacht stehenden Gildenmitglieder (Grimzle, Skrav, Blique, Nogle, Kathan) auflistet; einer davon ist der Verräter in der Blattgold-Händlergilde (letztlich Grimzle). Das Protokoll dient als Leitfaden für die Befragung von fünf NPCs und das Sammeln der Beweise.",loc:"Wird von Shakatu im Blattgold-Gildenhaus übergeben, nachdem das erste Questziel der Faktionsquest \"Glut gelöscht\" abgeschlossen ist. Quelle: Fextralife, VULKK, GameRant, Game8",miss:false,conf:"high",icon:"cd_assets/items/investigative-log-extinguish-the-flames.webp"},
  {name:"Letter to Younger Sibling",cat:"Quest-Dokument & Notiz",detail:"Ein Lese-Brief eines im Schneesturm gefundenen Soldaten an sein jüngeres Geschwister (questlog-Name: 'Letter to Younger Brother', ID 1001337; Wissenseintrag 'The Soldier Who Never Returned'), erfüllt von brüderlicher Liebe. Reines Story-/Lore-Dokument unter den Schlüssel-Items.",loc:"Auf der Leiche eines im Schneesturm umgekommenen Soldaten. Quelle: Fextralife, Questlog.gg, Gamer Guides",miss:true,conf:"high",icon:"cd_assets/items/letter-to-younger-sibling.webp"},
  {name:"Lost Letter",cat:"Quest-Dokument & Notiz",detail:"Ein Lese-Brief, der von einem mysteriösen Fremden überreicht wird, der danach spurlos verschwindet. Zum Lesen wählt man im Inventar die Dokument-Kategorie (zwischen Postern und Steckbriefen); Kliff übersetzt den unverständlichen Text. Vermittelt Tutorial-/Wissens-Einträge (z. B. Ausdauer oder Geschärfte Sinne).",loc:"Wird von einem verdächtigen Fremden ausgehändigt, der sich danach in Luft auflöst. Quelle: PC Gamer, Fextralife",miss:true,conf:"high",icon:"cd_assets/items/lost-letter.webp"},
  {name:"Missing Wooly",cat:"Quest-Dokument & Notiz",detail:"Ein Aushang über ein verschwundenes Schaf namens Wooly. Nach dem Lesen wird daraus die Mission 'Vermisster Begleiter' auf der Karte freigeschaltet. Einer der vier Springtide-Mill-Aushänge (neben Stolen/Verschwundene Kühe, Hörnerdieb, Seltsame Geräusche aus der Höhle), deren Abschluss die Hauptquest 'The Dark Veil' freischaltet.",loc:"An der Anschlagtafel bei der Frühlingsmühle im Hernand-Gebiet, nachdem die Mühle befreit wurde, während der Quest 'Where Misery Gathers' (Kapitel 2: Goldene Gier). Quelle: Fextralife, Questlog.gg, PowerPyx",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_quest_800181.webp"},
  {name:"Note with a Suspicious Symbol",cat:"Quest-Dokument & Notiz",detail:"Eine Notiz mit einem verdächtigen Symbol (Outlaw-Token), die jeder Gesetzlose in Pywel beim Fangen oder Töten fallen lässt. Sie kann an Milizionäre in Pywel verschenkt werden und gewährt pro Notiz über 30 Vertrauen; drei Notizen plus ein weiteres Item ergeben volles Vertrauen, woraufhin die Milizionäre Geschenke wie Munition geben.",loc:"Drop von Gesetzlose in Pywel (eine Notiz pro festgenommenem oder getötetem Gesetzlosen). Quelle: Fextralife, Game8, thegameswiki, gamerblurb",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_foldednote_0001.webp"},
  {name:"Proof of Stay",cat:"Quest-Dokument & Notiz",detail:"Ein Lese-Dokument, das als Beweisstück in der Fraktionsquest \"Glut gelöscht\" dient. Der Text belegt, dass Skrav für 6 Silbermünzen das vierte Zimmer im zweiten Stock des Demeniss-Gasthauses (ausgestellt von Linda) bewohnt hat, und wird Shakatu vorgelegt, um ihn an das gestohlene Hauptbuch in Grimzles Obhut zu erinnern.",loc:"Liegt auf einem Tisch in der Holzfäller-Werkstatt (Scheune) nahe Grimzles Haus im Coalvale-Workshop; die Tür ist verschlossen und der Questmarker führt hin. Teil der Quest \"Grimzle, the Ledger Manager\" innerhalb von \"Glut gelöscht\". Quelle: Fextralife, camzillasmom",miss:true,conf:"high",icon:"/assets/_sprites/itemicon_goblin_merchant_warranty.webp"},
  {name:"Renee's Poster",cat:"Quest-Dokument & Notiz",detail:"Ein Aushang der Metzgerin Renee; das Lesen schaltet die Fraktionsquest „Anfrage von Renee“ (Aufträge in Hernand) frei. Renee bittet darin um Hilfe, für einen langjährigen Kunden Fischbrei zuzubereiten.",loc:"An der Anschlagtafel in der Stadt Hernand zu finden; danach spricht man Renee in der Stadt persönlich an. Quelle: Game8, The Games Wiki",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0199.webp"},
  {name:"Rhett's Poster",cat:"Quest-Dokument & Notiz",detail:"Ein Aushang vom Schwarzen Brett, der die Faktions-/Nebenquest \"Anfrage von Rhett\" freischaltet, sobald man ihn liest und lernt. Die eigentliche Quest startet erst, wenn man danach den Schmied Rhett anspricht.",loc:"Wird von der Anschlagtafel (Schwarzes Brett) am Plaza in der Stadt Hernand gelesen; alternativ wird die Quest nach Abschluss anderer Hernand-Commissions wie Renee's oder Anfrage von Turnali verfügbar. Quelle: Game8, GameRant",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0044.webp"},
  {name:"Royal Delivery Note",cat:"Quest-Dokument & Notiz",detail:"Eine vom königlichen Lieferposten stammende Notiz (questlog-Name: 'Royal Trading Post Note', ID 1002475, DE 'Königliche Liefernotiz'), die das Ziel einer königlichen Lieferung beschreibt; sie verrät, dass der gesuchte Kunde zum Löwenmähne-Anwesen gereist ist, und treibt \"Anfrage von Bruna\" voran. Kann nicht verkauft oder weggeworfen werden.",loc:"Wird am Königlichen Handelsposten in der Stadt Hernand erlangt, indem man den Adligen (Adliger) mit rotem Hut wiederholt anspricht, bis man die Notiz erhält. Quelle: Game8, Fextralife",miss:false,conf:"high",icon:"cd_assets/items/royal-delivery-note.webp"},
  {name:"Sealed Letter",cat:"Quest-Dokument & Notiz",detail:"Ein Brief von einer geheimnisvollen Frau, der durch mystische Kraft versiegelt ist, sodass sein Inhalt zunächst nicht gelesen werden kann. Als Schlüssel-Item kann er nicht verkauft werden. Im weiteren Hauptquestverlauf wird er entsiegelt (Entsiegelter Brief) und enthüllt, dass die Hexen ein besonderes Item gegen den Zerfall des Abyss fertigen können.",loc:"Wird erbeutet, indem man den gefesselten Adligen in den Kanälen (Sewers) während der Quest \"In Freundlichkeit liegt wahre Weisheit\" befreit; einsehbar bei den lila Schlüssel-Items oben im Inventar. Später gibt Damiane in der Hauptquest \"Das fehlende Siegel\" die entsiegelte Fassung. Quelle: Fextralife, PC Gamer, Gamer Guides",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_cd_seal_epistle.webp"},
  {name:"Shakatu's Letter",cat:"Quest-Dokument & Notiz",detail:"Ein Brief von Shakatu, der gehört hat, dass man sich auf dem Heulenden Hügel niedergelassen hat, und sich für die geleistete Hilfe bedankt, indem er ein bescheidenes Geschenk für das neue Heim ankündigt. Reines Lese-Dokument ohne funktionalen Nutzen.",loc:"Wird durch Interaktion mit der Drachenkopf-Statue (Drachen-Totem) im Schrein-Bereich des Lagers auf dem Heulenden Hügel erhalten. Man muss um die Rückseite des Totems herumgehen, bis die Interaktion erscheint, da der Brief dort und nicht an der dekorativen Vorderseite versteckt ist. Teil der Hauptquest 'Eine sanfte Berührung' aus der Pioneering-Questreihe (Kapitel 3: Heulender Hügel). Quelle: Fextralife, Nerdschalk, Camzillasmom, PowerPyx",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0034.webp"},
  {name:"Stolen Cows",cat:"Quest-Dokument & Notiz",detail:"Ein Aushang über gestohlene Kühe (von Bremer aus dem Hernand-Bauernhof; questlog-Name des Posters: 'Verschwundene Kühe', ID 1002141, DE 'Verschwundene Kühe'), der von der Anschlagtafel genommen und gelesen werden kann. Das Lesen schaltet die Quest 'Eine Prüfung nach der anderen' frei; einer der vier Aushänge, deren Abschluss zu 'The Dark Veil' führt.",loc:"An der Anschlagtafel bei der Frühlingsmühle im Hernand-Gebiet (nach Befreiung der Mühle) während der Quest 'Where Misery Gathers' (Kapitel 2: Goldene Gier). Quelle: Fextralife, PowerPyx",miss:false,conf:"high",icon:"cd_assets/items/stolen-cows.webp"},
  {name:"Strange Noises from the Cave",cat:"Quest-Dokument & Notiz",detail:"Ein Aushang, der von seltsamen Geräuschen aus einer Höhle südlich von Hernand berichtet. Das Lesen schaltet die Quest 'Secrets Hidden in the Dark' frei; einer der vier Aushänge, deren Abschluss die Hauptquest 'The Dark Veil' freischaltet.",loc:"An der Anschlagtafel bei der Frühlingsmühle, südlich der Stadt Hernand (nach Befreiung der Mühle), während der Quest 'Where Misery Gathers' (Kapitel 2: Goldene Gier). Quelle: Fextralife, Questlog.gg, GamerGuides, PowerPyx",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_quest_800192.webp"},
  {name:"Tack Keeper's Note",cat:"Quest-Dokument & Notiz",detail:"Eine vom Sattelwart (Tack Keeper) hinterlassene Notiz (questlog-Name: 'Saddler's Note', ID 1002415, DE 'Notiz der Sattlerin': 'A note found at the stable in Hernand.') im Rahmen von \"Anfrage von Bruna\"; sie erklärt, dass der gesuchte Sattler vorübergehend abwesend ist und zum Königlichen Handelsposten weitergezogen ist.",loc:"Liegt auf einem Fass hinter dem Gebäude am Stable (Stall) nördlich der Stadt Hernand und ist als violettes Dokument-Symbol auf der Minimap markiert; gehört zur Quest \"Anfrage von Bruna\". Quelle: Game8, The Games Wiki",miss:false,conf:"high",icon:"cd_assets/items/tack-keeper-s-note.webp"},
  {name:"Tales of Sunset Valley",cat:"Quest-Dokument & Notiz",detail:"Eine Sammlung der düsteren Geschichten vom Sonnenuntergangstal, darunter bizarre Erzählungen über böse Geister, die im Schilf flüstern, und eine Vogelscheuche, die in den Wahnsinn führt. Lesbares Buch-Dokument.",loc:"Auffindbar im Gebiet Sonnenuntergangstal/Hernand; in den Datenbanken als Buch geführt (interne ID book_hernand_story). Fextralife kategorisiert es als Schlüssel-Gegenstand, inhaltlich ist es ein Lesebuch. Quelle: Fextralife, Questlog.gg, crimsondesert.gaming.tools",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_gimmick_item_book_07.webp"},
  {name:"Tavern Ledger",cat:"Quest-Dokument & Notiz",detail:"Ein Schankbuch der Hernand-Schenke (Namen Nogle und Grimzle, 50 Kupfermünzen, 10 Flaschen Wein am hintersten Tisch). Es wird Shakatu als Beweis vorgelegt, dass Nogle die Handelsroute preisgab, als er mit Grimzle in der Taverne trank.",loc:"Im Blattgold-Gildenhaus, wo Nogle einen Laden prüft; auf einer Kiste unter der Fleischware des Ladens, neben gestapelten Fässern. Teil der Teilquest \"Nogle, the Handelsverwalter\" in \"Glut gelöscht\". Quelle: Fextralife, camzillasmom",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_goblin_merchant_warranty.webp"},
  {name:"Tina's Poster",cat:"Quest-Dokument & Notiz",detail:"Ein Aushang der Schneiderin Tina; nach dem Aufnehmen wird ab Kapitel 3 die Fraktionsquest „Anfrage von Tina“ (Aufträge in Hernand) verfügbar. Tina hat einen Hut fertig, kann ihren Laden aber nicht verlassen und bittet um die Auslieferung.",loc:"An der Anschlagtafel in der Stadt Hernand zu finden; Tinas Laden liegt direkt neben dem Ausrüstungsladen (Rhett's Shop). Quelle: Game8, Fextralife",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0160.webp"},
  {name:"Trade Schedule Log",cat:"Quest-Dokument & Notiz",detail:"Ein Handelsplan-Logbuch (12 Ballen Seide, 5 Silbermünzen, Transaktionsmanager Nogle; Notiz: die Seide wird von der Goldleaf-Gilde zum Hafen transportiert). Es wird als Beweis vorgelegt; Shakatu hält Skrav daraufhin für verdächtig, was aber noch nicht reicht, um den wahren Verräter zu fassen.",loc:"Hinten im Stoffladen am Handelsposten der Blattgold-Händlergilde, auf einer Kiste, dort wo man mit Skrav gesprochen hat; Teil der Teilquest \"Skrav, the Handelsverwalter\" in \"Glut gelöscht\". Quelle: Fextralife, camzillasmom, GAMERPILLAR",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0223.webp"},
  {name:"Turnali's Poster",cat:"Quest-Dokument & Notiz",detail:"Ein Aushang, der die Faktionsquest \"Anfrage von Turnali\" freischaltet, wenn man ihn liest und lernt. Im Text bittet der Schmied Turnali um Hilfe; die Quest führt in die Spielsysteme Holzfällen (Logging) und Ausrüstungs-Refinement ein.",loc:"Wird von der Anschlagtafel (Schwarzes Brett) am Plaza in der Stadt Hernand abgenommen; alternativ kann man direkt zu Turnalis Schmiede nordöstlich des Bretts gehen. Quelle: Fextralife, Game8",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0201.webp"},
  {name:"Turnali's Smithy Flyer",cat:"Quest-Dokument & Notiz",detail:"Ein Werbeflyer für die Schmiede, scheinbar von Turnali selbst verfasst. Das Lesen erklärt die Ausrüstungs-Veredelung (Refinement): An der Schmiede lässt sich Ausrüstung mit genügend Materialien aufwerten.",loc:"In der Stadt Hernand während der Fraktionsquest „Anfrage von Turnali“; Turnali übergibt ihn zusammen mit einem Becker-Schild und 10x Bauholz als Belohnung für das Aushändigen des Hochwertigen Holzes. Quelle: Fextralife, Sportskeeda",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0245.webp"},
  {name:"Ugmon's Poster",cat:"Quest-Dokument & Notiz",detail:"Ein Aushang von Uggmon, der jemanden mit ausgeprägtem Geschmacks- und Geruchssinn sucht. Das Lesen schaltet die Fraktionsquest „Anfrage von Uggmon“ (Aufträge in Hernand) frei.",loc:"An der Anschlagtafel in der Stadt Hernand (ab Kapitel 3); Uggmon selbst sitzt im Blattgold-Gildenhaus nahe Einhornklippe. Quelle: Camzillasmom, Nerdschalk",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0190.webp"},
  {name:"Unsealed Letter",cat:"Quest-Dokument & Notiz",detail:"Beschrieben als \"ein Brief, entsiegelt, da die mystische Kraft verblasst ist\". Es ist der Brief der Weißen Krähe, dessen Siegel sich löst; er warnt vor der bröckelnden Grenze zwischen Abyss und Wirklichkeit. Beim Lesen erfährt man, dass Hexen ein besonderes Mittel gegen den Abyss-Zerfall herstellen können, was die Fraktionsquest \"Hexe der Weisheit\" auslöst.",loc:"Wird von Damiane in der Stadt Hernand im Verlauf der Hauptquest \"Das fehlende Siegel\" ausgehändigt und sofort im Inventar (lila Schlüssel-Item) gelesen. Quelle: Fextralife, PowerPyx",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0241.webp"},
  {name:"Wisdom between Donation and Fruition",cat:"Quest-Dokument & Notiz",detail:"Eine Notiz mit Details zu Bekehrungs- bzw. Missionierungsaktivitäten (conversion activities). Reines Lese-Dokument, das nach der Übergabe gelesen werden soll.",loc:"Wird in der Kirche von Hernand (Solumen-Orden, Stadt Hernand) erhalten; ein Priester auf der rechten Seite der Kirche begrüßt den Spieler und überreicht die Notiz. Quelle: Fextralife, crimsondesert.gaming.tools, Questlog.gg, GamerGuides",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0239.webp"},
  {name:"Ugmon's Note",cat:"Quest-Dokument & Notiz",detail:"Eine als Schlüssel-Gegenstand geführte Notiz von Uggmon vom Handelszentrum Blattgold-Gildenhaus. Reines Lese-/Questdokument im Rahmen von „Anfrage von Uggmon“; kann nicht verkauft werden.",loc:"Im Verlauf von „Anfrage von Uggmon“ rund um Uggmon am Blattgold-Gildenhaus erhältlich; die genaue Aufnahme ist in den Quellen nicht näher spezifiziert. Quelle: Fextralife",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0148.webp"},
];
